/* V169: the previous handler swallowed the server error entirely (`catch{}`) and always told
   the owner to check their name, phone and business details. The most common real cause is
   `open_application_already_exists` — the owner has ALREADY applied and is waiting on, or has
   already received, a decision. Telling them to correct correct data sent them in a loop.
   Every distinct server condition now maps to what the owner should actually do next. */
function manualApplicationOwnerMessageV169(error){
  const raw=String(error?.message||error?.hint||'');
  if(/open_application_already_exists/i.test(raw))
    return 'You already have a manual-payment application with Peekaa. Nothing further is needed — the team will contact you, or ask Peekaa admin to activate your approved workspace.';
  if(/already assigned to a business workspace/i.test(raw))
    return 'This account already has a Peekaa workspace. Sign out and sign back in to open it.';
  if(/application_idempotency_conflict/i.test(raw))
    return 'Your details changed since the last attempt. Reload this page and submit once more.';
  if(/published_sector_required/i.test(raw))
    return 'That business sector is not available yet. Choose another sector, or email admin.peekaa@gmail.com.';
  if(/confirmed owner email required/i.test(raw))
    return 'Confirm your email address first — check your inbox for the Peekaa confirmation link, then retry.';
  if(/valid business application fields are required/i.test(raw))
    return 'Check the billing mobile is a real Singapore number (for example 8123 4567), and that your name and business name are filled in above.';
  return 'Could not submit this manual-payment request right now. Nothing was charged. Retry, or email admin.peekaa@gmail.com.';
}
function wireManualBusinessApplicationFallback(){
  const button=$('requestManualBusinessHelp');
  if(!button)return;
  button.onclick=async()=>{
    const status=$('manualBusinessHelpStatus');
    const phone=String($('manualContactPhone')?.value||'').replace(/[^\d+]/g,'');
    const normalizedPhone=phone.startsWith('+')?phone:`+65${phone.replace(/\D/g,'')}`;
    /* Inline mode reuses the main setup form the owner already filled in. */
    const field=(manualId,mainId)=>String($(manualId)?.value??$(mainId)?.value??'').trim();
    const contactName=field('manualOwnerFullName','ownerFullName');
    const businessName=field('manualBusinessName','businessName');
    const sectorKey=field('manualBusinessSector','businessSector');
    const registration=field('manualBusinessRegistration','businessRegistration');
    if(contactName.length<2||businessName.length<2){
      if(status)status.textContent='Fill in your full name and business name above before requesting manual payment.';
      return;
    }
    if(!/^\+[1-9][0-9]{7,14}$/.test(normalizedPhone)){
      if(status)status.textContent='Enter a valid billing mobile, for example 8123 4567.';
      return;
    }
    let key=sessionStorage.getItem('nestly-self-serve-manual-application');
    if(!key){key=crypto.randomUUID();sessionStorage.setItem('nestly-self-serve-manual-application',key)}
    button.disabled=true;
    if(status)status.textContent='Sending this manual-payment application to the Peekaa admin queue…';
    try{
      const result=await sb.rpc('request_self_serve_manual_application_v159',{
        p_contact_name:contactName,
        p_contact_phone:normalizedPhone,
        p_business_name:businessName,
        p_sector_key:sectorKey,
        p_registration_number:registration||null,
        p_locale:businessApplicationLanguage(),
        p_idempotency_key:key
      });
      if(result.error)throw result.error;
      sessionStorage.removeItem('nestly-self-serve-manual-application');
      if(status)status.textContent='Sent. Super Admin can now see this manual-payment application in Platform → Onboarding and approve or reject it after payment is verified.';
    }catch(error){
      button.disabled=false;
      if(status)status.textContent=manualApplicationOwnerMessageV169(error);
      return;
    }
  };
}
function renderOnboard(){
  const setupEpoch=++businessSetupRenderEpoch;
  if(NestlyNativeBridge.isNative){renderNativeBusinessCompanion();return}
  root.innerHTML=`<main class="center-wrap" id="main" tabindex="-1"><section class="card" style="width:760px;max-width:100%;text-align:center"><div class="logo">${brandWordmark()}</div><h1 style="font-size:1.55rem;margin-top:18px">Loading secure business setup…</h1><p class="muted small" style="margin-top:7px">Checking current plans and any saved payment step.</p>${businessSetupAccountHtml()}${accountDeletionCardHtml()}${legalLinks()}</section></main>`;
  wireBusinessSetupAccount();wireAccountDeletionButton();
  const finishCheckout=(onboarding,statusNode,button)=>
    driveSelfServeCheckoutV281(onboarding,statusNode,button);
  (async()=>{
    const state=await sb.rpc('get_self_serve_checkout_v130',{p_business:null});
    if(setupEpoch!==businessSetupRenderEpoch)return;
    if(state.error||!state.data){
      root.innerHTML=`<main class="center-wrap" id="main" tabindex="-1"><section class="card" style="width:620px;max-width:100%;text-align:center"><h1 style="font-size:1.55rem">Business setup unavailable</h1><p class="muted small" style="margin-top:8px">We could not safely load the current Razorpay plans. No workspace or charge was created.</p>${businessSetupAccountHtml()}<button class="btn" id="onboardRetry" style="margin-top:4px">Retry</button>${accountDeletionCardHtml()}${legalLinks()}</section></main>`;
      wireBusinessSetupAccount();wireAccountDeletionButton();$('onboardRetry').onclick=renderOnboard;return;
    }
    const onboarding=state.data.onboarding;
    if(onboarding?.status==='active'){
      /* v770: same reason as the poll above — never hand off on caches older than the activation. */
      invalidateWorkspaceBootstrapCachesV370();
      nav(`#/workspace/${encodeURIComponent(onboarding.business_slug)}/dashboard`);return;
    }
    if(onboarding?.status==='payment_pending'){
      renderSelfServePaymentPendingV286(onboarding);
      return;
    }
    const plans=Array.isArray(state.data.plans)?state.data.plans:[];
    const sectors=Array.isArray(state.data.sectors)?state.data.sectors:[];
    const annual=plans.find(plan=>plan.cadence==='annual'),monthly=plans.find(plan=>plan.cadence==='monthly');
    if(!annual||!monthly||!sectors.length){
      const planGap=!annual&&!monthly?'Monthly and annual Razorpay plans are not active.':!annual?'Annual Razorpay plan is not active.':!monthly?'Monthly Razorpay plan is not active.':'Razorpay plans are available.';
      const sectorGap=sectors.length?'Eligible business sectors are published.':'No eligible business sector is published.';
      root.innerHTML=`<main class="center-wrap" id="main" tabindex="-1"><section class="card" style="width:760px;max-width:100%;text-align:left"><div class="logo" style="text-align:center">${brandWordmark()}</div><h1 style="font-size:1.6rem;margin-top:18px;text-align:center">Payment setup needs help</h1><p class="muted small" style="margin-top:8px;text-align:center">A Razorpay checkout window cannot open until Peekaa has active monthly and annual Razorpay plans plus at least one eligible business sector. No workspace, invoice, receipt, or charge was created.</p>${businessSetupAccountHtml()}<div class="card" style="margin-top:16px;background:var(--sand)"><b>Why Razorpay did not open</b><ul class="small" style="margin:8px 0 0;padding-left:18px"><li>${esc(planGap)}</li><li>${esc(sectorGap)}</li></ul></div>${sectors.length?manualBusinessApplicationFallbackHtml(sectors):`<div class="err" style="margin-top:16px">Business sectors are not ready, so manual application capture is temporarily unavailable. Contact Peekaa support.</div>`}<div class="row" style="justify-content:center;margin-top:16px"><button class="btn ghost" id="onboardRetry">Check Razorpay setup again</button><a class="btn ghost" href="mailto:admin.peekaa@gmail.com?subject=Peekaa%20subscription%20setup">Email Peekaa support</a></div>${accountDeletionCardHtml()}${legalLinks()}</section></main>`;wireBusinessSetupAccount();wireAccountDeletionButton();wireManualBusinessApplicationFallback();$('onboardRetry').onclick=renderOnboard;return;
    }
    /* nestly_v664: signup prices from the same tier ladder the workspace and the server use, and
       offers only tiers Peekaa can actually charge for — an owner cannot pick a capacity that the
       Stripe hand-off would refuse after their workspace row already exists. */
    const signupTiersV664=(Array.isArray(state.data.capacity_tiers)?state.data.capacity_tiers:[])
      .filter(tier=>tier&&Number(tier.capacity_ceiling)>0);
    const signupTiersForV664=cadence=>signupTiersV664
      .filter(tier=>tier.cadence===cadence&&tier.checkout_available!==false)
      .sort((left,right)=>Number(left.capacity_ceiling)-Number(right.capacity_ceiling));
    const signupTierV664=(cadence,capacity)=>signupTiersForV664(cadence)
      .find(tier=>Number(tier.capacity_ceiling)>=Number(capacity))||null;
    const signupTopTierV664=(()=>{
      const ladder=signupTiersForV664('annual');
      return ladder.length?Number(ladder[ladder.length-1].capacity_ceiling):0;
    })();
    const capacityOptions=signupTiersForV664('annual').map(tier=>Number(tier.capacity_ceiling));
    if(!capacityOptions.length)capacityOptions.push(10000);
    root.innerHTML=`<main class="center-wrap" id="main" tabindex="-1"><section class="card" style="width:820px;max-width:100%"><div class="logo">${brandWordmark()}</div><h1 style="font-size:1.7rem;margin-top:18px">Set up your business</h1><p class="muted small" style="margin-top:7px">Enter your business details, then choose how you want to pay. Paying by card opens your workspace automatically once Razorpay confirms payment; paying manually sends the details to Peekaa admin, who opens your workspace after checking payment.</p><div class="grid2" style="margin-top:18px"><div><label for="ownerFullName">Your full name</label><input id="ownerFullName" autocomplete="name"></div><div><label for="businessName">Business name</label><input id="businessName" autocomplete="organization"></div><div><label for="businessSector">Business sector</label><select id="businessSector">${sectors.map(sector=>`<option value="${esc(sector.sector_key)}">${esc(sector.label)}</option>`).join('')}</select></div><div><label for="businessRegistration">UEN / registration number (optional)</label><input id="businessRegistration" autocomplete="off"></div></div><label for="businessSlug">Workspace address</label><div class="row"><span class="muted small">peekaa.asia/business/</span><input id="businessSlug" autocomplete="off"></div><fieldset id="payMethodChoice" style="border:0;padding:0;margin:22px 0 0"><legend style="font-weight:700">How would you like to pay?</legend><p class="muted small" style="margin-top:4px">Choose one. Nothing is charged until you confirm.</p><div class="row" style="align-items:stretch;flex-wrap:wrap;margin-top:10px"><label class="card" style="flex:1;min-width:220px;cursor:pointer"><input type="radio" name="payMethod" value="stripe"> <strong>Pay by card now</strong><p class="muted small" style="margin-top:5px">Secure Razorpay Checkout. Your workspace opens automatically once payment is confirmed.</p></label><label class="card" style="flex:1;min-width:220px;cursor:pointer"><input type="radio" name="payMethod" value="manual"> <strong>Pay manually</strong><p class="muted small" style="margin-top:5px">Bank transfer, cash or another arrangement. Peekaa admin opens your workspace after checking payment.</p></label></div></fieldset><div id="payStripeBlock" hidden><fieldset style="border:0;padding:0;margin:20px 0 0"><legend style="font-weight:700">Billing cycle</legend><div class="row" style="align-items:stretch;flex-wrap:wrap;margin-top:8px"><label class="card" style="flex:1;min-width:220px;cursor:pointer"><input type="radio" name="selfServeCadence" value="annual" checked> <strong>Annual · <span id="selfServeAnnualPrice">${money(annual.base_amount_cents)}</span>/year</strong><p class="muted small" style="margin-top:5px"><span id="selfServeAnnualEquivalent">${money(Math.round(annual.base_amount_cents/12))}</span>/month equivalent · best value</p></label><label class="card" style="flex:1;min-width:220px;cursor:pointer"><input type="radio" name="selfServeCadence" value="monthly"> <strong>Monthly · <span id="selfServeMonthlyPrice">${money(monthly.base_amount_cents)}</span>/month</strong><p class="muted small" style="margin-top:5px" id="selfServeMonthlyNote">Flexible monthly billing</p></label></div></fieldset><label for="customerCapacity">Customer capacity</label><select id="customerCapacity">${capacityOptions.map(value=>`<option value="${value}">Up to ${value.toLocaleString('en-SG')} customer profiles</option>`).join('')}</select><p class="muted small" id="selfServeCapacityNote" style="margin-top:6px"></p><div class="card" style="margin-top:16px;background:var(--sand)"><span class="muted small">Amount due</span><div id="selfServeTotal" style="font-size:1.8rem;font-weight:750;margin-top:3px"></div><p class="muted small" style="margin-top:5px">GST not charged · staff access included · Subscription fees are non-refundable after payment, except where required by law</p></div><details style="margin-top:16px"><summary style="font-weight:700;cursor:pointer">What is included</summary><ul class="small" style="columns:2;column-width:240px">${(state.data.included_modules||[]).map(item=>`<li>${esc(item)}</li>`).join('')}</ul></details><label class="checkrow" for="onboardLegalConsent" style="margin-top:18px"><input id="onboardLegalConsent" type="checkbox" aria-label="I agree to the Terms of Service and acknowledge the Privacy Policy"><span>I agree to the <a class="consent-document-link" href="/terms.html?return=business-signup" target="_blank" rel="noopener">Terms of Service</a> and acknowledge the <a class="consent-document-link" href="/privacy.html?return=business-signup" target="_blank" rel="noopener">Privacy Policy</a>.</span></label><div id="onboardError" role="alert"></div><button class="btn" id="startSelfServe" style="width:100%;margin-top:18px">Continue to secure Razorpay Checkout</button><p class="muted small" id="onboardStatus" role="status" aria-live="polite" style="margin-top:8px">No payment details are entered in Peekaa.</p></div><div id="payManualBlock" hidden>${manualBusinessApplicationFallbackHtml(sectors,{inline:true})}</div><hr style="border:none;border-top:1px solid var(--line);margin:22px 0 14px"><b>Joining a team instead?</b><div class="row" style="margin-top:10px"><input id="ic" placeholder="Invite code from your boss" style="text-transform:uppercase;max-width:260px"><button class="btn ghost" id="join">Join team</button><span class="spacer"></span><button class="btn ghost sm" id="out">Sign out</button></div>${accountDeletionCardHtml()}${legalLinks()}</section></main>`;
    const setupIntroduction=root.querySelector('main section.card>p');
    if(setupIntroduction)setupIntroduction.insertAdjacentHTML('afterend',businessSetupAccountHtml('businessSetupSignOut'));
    wireBusinessSetupAccount('businessSetupSignOut');wireAccountDeletionButton();
    let slugEdited=false;
    const slugify=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80);
    $('businessName').oninput=()=>{if(!slugEdited)$('businessSlug').value=slugify($('businessName').value)};
    $('businessSlug').oninput=()=>{slugEdited=true;$('businessSlug').value=slugify($('businessSlug').value)};
    const updateTotal=()=>{
      const cadence=root.querySelector('[name="selfServeCadence"]:checked')?.value||'annual';
      const capacity=Number($('customerCapacity').value||10000);
      const tier=signupTierV664(cadence,capacity);
      const startButton=$('startSelfServe');
      if(startButton)startButton.disabled=!tier;
      $('selfServeTotal').textContent=tier
        ?`${money(tier.amount_cents)} / ${cadence==='annual'?'year':'month'}`
        :'Arranged with Peekaa support';
      $('selfServeCapacityNote').textContent=tier
        ?`Up to ${capacity.toLocaleString('en-SG')} customer profiles across every branch. Each branch you add later is charged this amount again, for the time left in the period. More than ${signupTopTierV664.toLocaleString('en-SG')} profiles is arranged with Peekaa support.`
        :`${cadence==='annual'?'Annual':'Monthly'} billing is not offered at this capacity — contact admin.peekaa@gmail.com.`;
      /* Both cadence cards price the capacity actually chosen, so the headline and the amount due
         can never disagree. A cadence with no tier at this capacity says so on its own card. */
      const annualTier=signupTierV664('annual',capacity),monthlyTier=signupTierV664('monthly',capacity);
      $('selfServeAnnualPrice').textContent=annualTier?money(annualTier.amount_cents):'—';
      $('selfServeAnnualEquivalent').textContent=annualTier?money(Math.round(annualTier.amount_cents/12)):'—';
      $('selfServeMonthlyPrice').textContent=monthlyTier?money(monthlyTier.amount_cents):'—';
      $('selfServeMonthlyNote').textContent=monthlyTier?'Flexible monthly billing':'Not offered at this capacity';
    };
    root.querySelectorAll('[name="selfServeCadence"]').forEach(input=>input.onchange=updateTotal);$('customerCapacity').onchange=updateTotal;updateTotal();wireManualBusinessApplicationFallback();
    /* V169: neither payment path renders until the owner picks one. Previously the Stripe form
       and the manual-payment form were both on screen at once, asking for overlapping details,
       so owners could not tell which route they were on or which button actually charged them. */
    root.querySelectorAll('[name="payMethod"]').forEach(input=>input.onchange=()=>{
      const stripeChosen=input.value==='stripe';
      $('payStripeBlock').hidden=!stripeChosen;
      $('payManualBlock').hidden=stripeChosen;
      (stripeChosen?$('payStripeBlock'):$('payManualBlock'))
        .scrollIntoView({block:'nearest',behavior:'smooth'});
    });
    $('startSelfServe').onclick=async()=>{
      const cadence=root.querySelector('[name="selfServeCadence"]:checked')?.value||'annual';
      const setupKey=sessionStorage.getItem('nestly-self-serve-setup')||crypto.randomUUID();sessionStorage.setItem('nestly-self-serve-setup',setupKey);
      if(!$('onboardLegalConsent').checked){$('onboardError').innerHTML='<div class="err">Please agree to the Terms of Service and acknowledge the Privacy Policy.</div>';return}
      $('startSelfServe').disabled=true;$('onboardStatus').textContent='Saving the locked workspace and server-priced plan…';
      invalidatePersonaCacheV370(); // V370: self-serve signup creates an owner persona
      const started=await sb.rpc('start_self_serve_business_v130',{
        p_owner_name:$('ownerFullName').value.trim(),p_business_name:$('businessName').value.trim(),
        p_business_slug:$('businessSlug').value.trim(),p_sector_key:$('businessSector').value,
        p_registration_number:$('businessRegistration').value.trim()||null,p_locale:businessApplicationLanguage(),
        p_cadence:cadence,p_customer_capacity:Number($('customerCapacity').value),
        p_legal_accepted:true,p_idempotency_key:setupKey
      });
      if(started.error||!started.data?.business_id){$('startSelfServe').disabled=false;$('onboardStatus').textContent='We could not save this setup. Check every field and choose another workspace address if it is already used.';return}
      const saved={business_id:started.data.business_id,cadence,customer_capacity:Number($('customerCapacity').value)};
      await finishCheckout(saved,$('onboardStatus'),$('startSelfServe'));
    };
    /* nestly_v588: the SECOND accept_invite call site, on the onboarding screen — it carried the
       exact bug the invite-accept page had: it assigned accept_invite's {status,message} payload
       to S.biz (corrupting the business object) and toasted a welcome at a person the server had
       just parked awaiting owner approval. Same treatment as renderBusinessStaffInviteAcceptV151:
       never touch S.biz, speak the server's own message, and land on the workspace route, whose
       v569 card names the wait. */
    $('join').onclick=async()=>{if(!$('ic').value.trim())return toast('Enter your invite code');$('join').disabled=true;invalidatePersonaCacheV370();const {data,error}=await sb.rpc('accept_invite',{p_code:$('ic').value});if(error){toast(humanErrorV295(error,'That invite code could not be used.'));$('join').disabled=false;return}
      const joinSlugV588=data?.business_slug||'';
      toast(data?.status==='approved'?'Welcome back — opening the workspace':(data?.message||'Joined — waiting for the owner to approve you'));
      nav(joinSlugV588?`#/workspace/${encodeURIComponent(joinSlugV588)}/dashboard`:'#/dashboard')};
    $('out').onclick=async()=>{killChannels();await sb.auth.signOut({scope:'local'});resetClientSessionState();route()};
  })();
}

function importBtn(moduleKey,label='Import',done='route'){
  const onDone=done==='settingsPage'?'settingsPage()':'route()';
  return CUI.action({label,iconName:'import',variant:'secondary',className:'sm',attributes:`onclick="openImport('${moduleKey}',()=>${onDone})"`});
}

/* ---------- shell ---------- */
/* V272: staffperf no longer has a nav entry of its own, so it borrows the Reports group it is
   reached from — otherwise the whole rail goes unlit on a route that is still reachable. */
function activeGroupKey(pageKey){
  const k=pageKey==='client'?'clients':['studio','storedvalue','promotions'].includes(pageKey)?'loyalty':pageKey==='staffperf'?'reports':pageKey;
  if(k==='grow')return 'grow';
  const g=NAVGROUPS.find(g=>g.items.includes(k));
  return g?g.key:null;
}
/* V296 (owner markup 2026-08-12: "remove"). The "← Back to Grow overview" header button that used
   to be built here sat on every grow submodule — Retention, Promotions, Referrals, Memberships and
   Gift cards. V295 removed it from the loyalty editor; the owner's ruling covers these headers too,
   now that the rail carries Programmes' own children and Gift cards sits under Serve & sell. The
   destination is one rail click away, so the capability did not leave with the button. */
/* V375: the customer portal link is built in one place now that two pages show it (Bookings
   keeps the Copy button, Appointments carries the card — owner, photo 5). */
function portalUrlV375(slug){return publicAppUrl(`b/${encodeURIComponent(slug||'')}`)}
function waitlistBadgeHtml(){
  const count=Number(waitlistActiveCount)||0;
  return count>0?`<span class="nav-badge" data-waitlist-badge>${count}</span>`:'';
}
function setWaitlistBadgeCount(count){
  waitlistActiveCount=Math.max(0,Number(count)||0);
  document.querySelectorAll('[data-waitlist-badge-slot]').forEach(slot=>{
    slot.innerHTML=waitlistBadgeHtml();
  });
}
async function refreshWaitlistBadge(){
  if(!S?.biz?.id||!canReadModule('waitlist')){setWaitlistBadgeCount(0);return}
  const ticket=++waitlistBadgeRequest;
  const {count,error}=await sb.from('waitlist').select('id',{count:'exact',head:true})
    .eq('business_id',S.biz.id).in('status',['waiting','contacted']);
  if(ticket!==waitlistBadgeRequest||error)return;
  setWaitlistBadgeCount(count||0);
}
function navHtml(page,idPrefix='nav'){
  /* V275: bottle keep is stripped from the resolved module list for every non-bar sector BEFORE
     the rail is built, so no other sector's navigation can gain a row even if an entitlement
     ever handed the key out by mistake. Every existing module rule below is untouched. */
  const sectorShowsBottlesV275=isBarSectorV275();
  const enabled=filterResolvedModulesForRole(S.myModules||S.biz.enabled_modules||[],S.myRole)
    .filter(module=>!HIDDEN_BUSINESS_SURFACES.has(module))
    .filter(module=>module!=='bottles'||sectorShowsBottlesV275);
  const activeKey=page[0]==='client'?'clients':page[0];
  const activeGrp=activeGroupKey(page[0]);
  /* V219. Owner: "add branch inside (so can add or manage branches using the module as well)".
     branchesPage exists and is routed, but the nav required 'branches' to be in the resolved
     module list — and it never is, because staff_module_perms is built from enabled_modules,
     which is fixed by the sector entitlement and does not include it. So an owner could create a
     branch from Settings and then had nowhere to manage one. Branches is structural and
     owner-only, exactly like Staff members, so it is offered on the same terms. */
  /* V223. Owner: "waitlist is tagged to bookings (so disable / enable together)". A waitlist
     holds the people a booking could not seat, so it has no meaning without the booking page
     that produces them — showing one without the other is a dead end. */
  /* V243: Customer Interface is owner-only on exactly the terms Settings is — it carries the
     sign-up QR, the customer-app switches and the programme presentation, which is the same
     authority the Settings tabs it absorbed already required. It is not in enabled_modules
     (it is a surface, not a sector entitlement), so it is offered like Branches is. */
    /* V246 (owner: "why cafe/F&B have appointment module? appointment is for a staff to serve
     the customer for a service. cafe is about bookings / table bookings and reservation -
     with a waitlist"). The sector decides the serving model: an F&B floor seats parties at
     tables (Bookings + Waitlist); a service sector books a person's time (Appointments).
     Nav-level only, deliberately: the route stays reachable, so an F&B tenant with historical
     appointments, a deep link or a Customer 360 hand-off is never stranded — the irrelevant
     module just stops being advertised. */
  const sectorHidesAppointmentsV246=sectorHidesAppointmentsV276();
  /* nestly_v570: 'dashboard' used to be an unconditional TRUE here — the one module key the rail
     advertised no matter what the owner had granted. So an owner who set Dashboard to Off in the
     per-staff module editor still saw the row in that staff member's rail, and the row still
     opened. It participates in the same `enabled.includes(m)` test as every other module now,
     which is all it ever needed: 'dashboard' is a real key in ALLMODS, in every sector bundle
     and in staff_module_perms, so an inheriting staff member and every owner keep the row. */
  /* nestly_v768: a retired module is never a rail row, whatever the entitlement says. */
  const navModuleVisible=m=>!RETIRED_BUSINESS_MODULES_V768.has(m)&&((m==='dashboard'&&enabled.includes('dashboard'))
    ||(m==='staffmembers'&&(S.myRole==='owner'||S.myRole==='manager'))
    ||(m==='branches'&&S.myRole==='owner')
    ||(m==='customer-interface'&&S.myRole==='owner')
    ||(m==='remindernotify'&&S.myRole==='owner')
    ||(m==='bottlesetup'&&sectorShowsBottlesV275&&S.myRole==='owner')
    ||(m==='custpackages'&&enabled.includes('packages'))
    ||(m==='waitlist'&&enabled.includes('waitlist')&&enabled.includes('bookings'))
    ||(m!=='waitlist'&&m!=='appointments'&&enabled.includes(m))
    ||(m==='appointments'&&!sectorHidesAppointmentsV246&&enabled.includes(m)));
  const visGroups=NAVGROUPS.map(g=>({...g,items:g.items.filter(navModuleVisible)})).filter(g=>g.items.length);
  return visGroups.map(g=>{
    if(g.flat){
      /* V250: a flat group whose destination is a surface rather than a module key declares its
         own href, and is then active for every route that resolves to the group — so Programmes
         stays lit on #/grow, #/grow/ongoing, #/grow/available and every drilled topic view,
         which a plain activeKey===items[0] comparison could never do. */
      const target=g.items[0];
      const href=g.href||`#/${target}`;
      const isAct=g.href?activeGrp===g.key:activeKey===target;
      return `<a href="${href}" class="${isAct?'act':''}"${isAct?' aria-current="page"':''}><span class="ic">${CUI.icon(g.icon,{size:20})}</span>${g.flat}</a>`;
    }
    if(!(g.key in navOpen)) navOpen[g.key]=(g.key===activeGrp);
    const isOpen=navOpen[g.key]||g.key===activeGrp;
    /* V294 (owner markup 2026-08-12): a group may declare `views` — routable children that are
       the destination page's own tabs (Programmes: Overview / List / History) rather than module
       surfaces. Active-state follows the open tab. Module routes inside the group (#/loyalty…)
       light only the header, exactly as before. */
    /* V296: generalised so Customer Interface can declare children the same way. A child's own
       href decides which route lights it; #/grow keeps its special case because every OTHER #/grow
       hash — the default list, a drilled topic, the legacy ongoing/available/settings deep links —
       belongs to List, which a plain segment comparison would leave unlit. */
    const navViewActiveV296=href=>{
      const parts=String(href||'').replace(/^#\//,'').split('/');
      const routeKey=parts[0]||'',routeView=parts[1]||'';
      /* Wave 2A: #/loyalty is an alias route onto the Rewards Programme landing — the rail child
         must light there too, not only on #/grow (audit §2F: two of eight screens had no
         location signal). */
      const pageKeyV2A=page[0]==='loyalty'?'grow':page[0];
      if(pageKeyV2A!==routeKey)return false;
      /* V319: 'offers' joins the set of #/grow hashes that belong to a SIBLING child rather than
         to the Rewards Programme list, so opening it no longer lights two rail rows at once. */
      if(routeKey==='grow')return routeView?page[1]===routeView:!['overview','history','offers'].includes(String(page[1]||''));
      /* V392: Customer Action is ONE rail row over a page with two tabs. Its row now carries the
         Appointment Setting hash (owner, photo 3: "when click this is the default page"), so
         without this the row would go dark the moment the owner switched to the Customer
         Permissions tab beside it — one row, both of its own tabs. */
      if(routeKey==='customer-interface'&&CUSTOMER_INTERFACE_TABS_V368.includes(routeView))
        return CUSTOMER_INTERFACE_TABS_V368.includes(String(page[1]||''));
      return String(page[1]||'')===routeView;
    };
    /* nestly_v538: a `views` group used to render ONLY its declared views, so a
       module-backed item inside such a group was silently dropped. Both are now
       rendered — views first (they are the host page's tabs), then any module
       items navModuleVisible let through. Groups with no module items are
       byte-identical to before, because the second list is empty for them. */
    const moduleChildRowsV538=items=>items.filter(m=>MODULES[m]).map(m=>`<a href="#/${m}" class="${activeKey===m?'act':''}"${activeKey===m?' aria-current="page"':''}><span class="ic">${CUI.icon(MODULES[m][0],{size:20})}</span><span class="nav-label">${MODULES[m][1]}</span>${m==='waitlist'?`<span data-waitlist-badge-slot>${waitlistBadgeHtml()}</span>`:''}${m==='appointments'?`<span data-appointments-badge-slot>${appointmentsNavBadgeHtml()}</span>`:''}</a>`).join('');
    const childRowsV294=(g.views||[]).length
      ?g.views.map(([label,href,iconName])=>{const on=navViewActiveV296(href);
        return `<a href="${href}" class="${on?'act':''}"${on?' aria-current="page"':''}><span class="ic">${CUI.icon(iconName||g.icon,{size:20})}</span><span class="nav-label">${label}</span></a>`}).join('')
        /* nestly_v546: a group may declare its items as ENTITLEMENT KEYS ONLY. They still gate
           whether the group appears, and every route still resolves; they just are not rail rows,
           because the group's own page already lists them. */
        +(g.gateOnly?'':moduleChildRowsV538(g.items))
      :g.items.filter(m=>MODULES[m]).map(m=>`<a href="#/${m}" class="${activeKey===m?'act':''}"${activeKey===m?' aria-current="page"':''}><span class="ic">${CUI.icon(MODULES[m][0],{size:20})}</span><span class="nav-label">${MODULES[m][1]}</span>${m==='waitlist'?`<span data-waitlist-badge-slot>${waitlistBadgeHtml()}</span>`:''}${m==='appointments'?`<span data-appointments-badge-slot>${appointmentsNavBadgeHtml()}</span>`:''}</a>`).join('');
    return `<div class="navgroup">
      <button type="button" class="navhead ${g.key===activeGrp?'act':''}" data-grp="${g.key}" aria-expanded="${isOpen}" aria-controls="${idPrefix}-${g.key}"><span class="ic">${CUI.icon(g.icon,{size:20})}</span>${g.label}<span class="chev" aria-hidden="true">${isOpen?'−':'+'}</span></button>
      <div class="navbody" id="${idPrefix}-${g.key}" data-body="${g.key}" style="display:${isOpen?'block':'none'}">
        ${childRowsV294}
      </div></div>`;
  }).join('');
}
function wireNav(){
  document.querySelectorAll('.navhead').forEach(el=>el.onclick=()=>{
    const k=el.dataset.grp;navOpen[k]=!navOpen[k];
    const body=document.getElementById(el.getAttribute('aria-controls'));
    if(!body)return;
    body.style.display=navOpen[k]?'block':'none';
    el.setAttribute('aria-expanded',String(navOpen[k]));
    el.querySelector('.chev').textContent=navOpen[k]?'−':'+';
  });
}
