function checkoutPointsReceiptV102({saleResult,packageResults=[],refreshedPoints=null}={}){
  const operations=[];
  if(saleResult&&Number.isFinite(Number(saleResult.pointsEarned))){
    operations.push({
      kind:'sale',
      pointsEarned:Number(saleResult.pointsEarned),
      pointsTotal:saleResult.pointsTotal!=null&&Number.isFinite(Number(saleResult.pointsTotal))
        ?Number(saleResult.pointsTotal):null
    });
  }
  for(const result of packageResults){
    if(!result||!Number.isFinite(Number(result.pointsEarned)))continue;
    operations.push({
      kind:'package',
      pointsEarned:Number(result.pointsEarned),
      pointsTotal:result.pointsTotal!=null&&Number.isFinite(Number(result.pointsTotal))
        ?Number(result.pointsTotal):null
    });
  }
  const lastOperationTotal=[...operations].reverse().find(item=>item.pointsTotal!=null)?.pointsTotal??null;
  const currentTotal=refreshedPoints!=null&&Number.isFinite(Number(refreshedPoints))
    ?Number(refreshedPoints):null;
  return {
    pointsEarned:operations.reduce((sum,item)=>sum+item.pointsEarned,0),
    // A writer receipt is the checkout snapshot. A later lookup is only a fallback when the
    // writer has no total; a mismatch may be unrelated concurrent ledger activity.
    pointsTotal:lastOperationTotal??currentTotal,
    balanceConsistent:lastOperationTotal==null||currentTotal==null||lastOperationTotal===currentTotal,
    operations
  };
}
function serviceDisplayName(service={}){
  const name=String(service.name||service.service_name||'Service').trim()||'Service';
  const variant=String(service.variant_label||'').trim();
  const duration=Number(service.duration_min);
  const detail=variant||(duration>0?`${duration} min`:'');
  return detail?`${name} · ${detail}`:name;
}
/* V385 (owner markup, photo 2, arrow on Print receipt: "click but nothing happened").
   The button called window.print() directly. In an iOS home-screen web app — which is how the
   owner was running the till, and how a counter tablet is meant to run it — window.print() is a
   documented no-op: no dialog, no error, no console message. Nothing happened is exactly what
   it does there.
   So the standalone case takes the route that DOES work: the receipt is written into a new
   browsing context, which on iOS opens in Safari where printing is available. The in-page path
   is kept for every browser where it already worked, now inside a try/catch with a cleanup
   timer — an exception used to leave the page stuck in its print-only stylesheet. And when
   neither route is available the owner is TOLD, rather than shown a button that does nothing. */
/* V388: the receipt code, big enough to scan off a screen, with the PNG offered. Drawn fresh at
   320px rather than scaling the 132px receipt bitmap, because an upscaled QR loses the crispness
   a scanner needs. The download is built from the canvas the library produces — no network, no
   second encoder — and when the CDN never arrived the url is still shown as text, which is the
   thing that actually matters. */
function openWalletQrDialogV388(url,businessName){
  document.getElementById('walletQrModalV388')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="walletQrModalV388" role="dialog" aria-modal="true" aria-labelledby="walletQrTitleV388" tabindex="-1"><div class="modal-card" style="max-width:420px">
    <div class="row"><div><h2 id="walletQrTitleV388" style="font-size:16px">Customer rewards code</h2><p class="muted small" style="margin-top:4px">Scan to open rewards, points and past visits at <span data-merchant-content>${esc(businessName)}</span>.</p></div><span class="spacer"></span><button class="btn ghost sm" id="walletQrCloseV388" type="button">Close</button></div>
    <div id="walletQrHostV388" class="wallet-qr-host-v388" role="status">Drawing the code…</div>
    <p class="small" style="word-break:break-all;margin-top:10px"><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a></p>
    <div class="row" style="margin-top:14px;gap:8px"><button class="btn sm" id="walletQrSaveV388" type="button" disabled>Save image</button></div>
  </div></div>`);
  const modal=document.getElementById('walletQrModalV388');
  let deactivate;
  const close=()=>{if(deactivate)deactivate();else modal?.remove()};
  deactivate=CUI.activateDialog(modal,{onClose:close,initialFocus:'#walletQrCloseV388'});
  document.getElementById('walletQrCloseV388').onclick=close;
  const host=document.getElementById('walletQrHostV388'),save=document.getElementById('walletQrSaveV388');
  void loadQrLibrary().then(()=>{
    if(!host.isConnected)return;
    host.innerHTML='';
    new QRCode(host,{text:url,width:320,height:320,correctLevel:QRCode.CorrectLevel.M});
    /* qrcodejs paints a canvas and an <img> of it; either can produce the PNG, and which one is
       present depends on the browser. */
    const png=()=>{
      const canvas=host.querySelector('canvas');
      if(canvas)return canvas.toDataURL('image/png');
      return host.querySelector('img')?.src||'';
    };
    save.disabled=false;
    save.onclick=()=>{
      const data=png();
      if(!data)return toast('The image could not be saved. Screenshot the code instead.');
      const link=document.createElement('a');
      link.href=data;link.download=`${BRAND.downloadPrefix}-rewards-qr.png`;
      document.body.appendChild(link);link.click();link.remove();
    };
  }).catch(()=>{
    if(!host.isConnected)return;
    host.innerHTML='<p class="muted small">The code could not be drawn. Share the link below instead.</p>';
  });
}
const posReceiptStandaloneV385=()=>globalThis.navigator?.standalone===true
  ||globalThis.matchMedia?.('(display-mode: standalone)')?.matches===true;
function printPosReceiptV385(){
  const receipt=document.getElementById('posReceiptV142');
  if(!receipt)return toast('The receipt is no longer on screen.');
  if(posReceiptStandaloneV385()){
    let printWindow=null;
    try{printWindow=window.open('','_blank')}catch(error){printWindow=null}
    if(!printWindow)return toast('Open peekaa.asia in Safari to print this receipt.');
    /* Only the receipt's own markup travels, and it is written as a plain document with its own
       styles — the app's stylesheet is fingerprinted per deploy and this window must not depend
       on a url that changes. No script is written into the new document. */
    printWindow.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Receipt</title>
      <meta name="viewport" content="width=device-width,initial-scale=1">
      <style>body{margin:0;padding:10mm;max-width:80mm;font:14px/1.45 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1b1b1b}
        .no-print{display:none}table{width:100%;border-collapse:collapse}img,canvas{max-width:100%}
        @media print{body{padding:4mm}}</style></head><body>${receipt.innerHTML}</body></html>`);
    printWindow.document.close();
    /* Give the written document — the wallet QR image in particular — a moment to lay out before
       the dialog freezes the page. focus() first, or Safari prints the opener on some versions. */
    setTimeout(()=>{try{printWindow.focus();printWindow.print()}catch(error){}},350);
    return;
  }
  document.body.classList.add('pos-receipt-print');
  const clear=()=>document.body.classList.remove('pos-receipt-print');
  window.addEventListener('afterprint',clear,{once:true});
  /* afterprint does not fire in every browser; the page must never be left print-only. */
  setTimeout(clear,60000);
  try{window.print()}catch(error){clear();toast('This browser could not open the print dialog.')}
}
/* nestly_v430 — the till's own unit noun. Every VALUE the counter shows was already pot-correct
   (the v155 lookup and v145's ask-the-server rule), but the labels hardcoded points: a stamps
   firm's counter read "764 pts" over 764 stamps, the receipt said "+6 points", and the voucher
   banner priced a stamp gift in points (go-live battery, 2026-08-22). One resolver, read off the
   same catalogue payload the v404 dialog already trusts; points wording is byte-identical to
   before for every points firm. */
function tillUnitNounV430(catalogRef,short){
  const stampsV430=catalogRef?.customerGiftsV392?.program?.unit==='stamps';
  return stampsV430?'stamps':(short?'pts':'points');
}
/* nestly_v474 (owner: "why it shows 15 stamps in record sale but customer view shows 5 out of 10
   stamps? it is way too messy. I need it to standardise").
   Both figures were true and neither was a bug — they are different QUANTITIES wearing the same
   word. The till printed the programme POT (every stamp ever earned minus redemptions); the
   customer's phone prints their position on THE CARD IN THEIR HAND. On the owner's own customer:
   pot 15, ten already consumed by a completed card, so five on a ten-slot card.
   The standard the owner asked for is the customer's card, because staff and customer talk across
   a counter and the number staff quote has to be the number on the phone being held up at them.
   v474 taught both staff reads to carry `stamp_card` beside the balance; this is the one place
   that turns it into words, so the till and the customer profile cannot word it differently.
   A points firm has no stamp_card and falls straight through to the balance it always printed —
   for points the pot IS what the customer sees, so there was never a discrepancy to fix. */
function stampCardStandingV474(card,balance,unitNoun){
  const slots=Math.max(0,Math.floor(Number(card?.slots)||0));
  if(!slots)return Number.isFinite(Number(balance))
    ?`${Number(balance).toLocaleString('en-SG')} ${unitNoun}`:'';
  const filled=Math.max(0,Math.min(slots,Math.floor(Number(card?.filled)||0)));
  /* The overflow is said out loud rather than dropped. A customer holding more than one card's
     worth is a real state — it is what their own app calls "N already counted toward your next
     card" — and staff who could not see it would be looking at a different truth again, which is
     the whole complaint. */
  const carried=Math.max(0,Math.floor(Number(card?.carried)||0));
  return `${filled} of ${slots} stamps${carried>0?` · ${carried.toLocaleString('en-SG')} toward the next card`:''}`;
}
/* nestly_v432 — the redeem-now list is grouped by WHERE each reward's eligibility comes from
   (owner ruling 2026-08-22: no hidden counter-only gifts; staff and Customer View read the same
   canonical availability, which the server now resolves in app.reward_availability_v432). The
   grouping is pure presentation: `source` arrives from the server per reward, this function only
   buckets and labels. A source this build does not know still renders — under a plain "Rewards"
   heading — because dropping a server-approved reward on the floor would be a second, client-side
   eligibility rule, which is exactly what v145 forbids. */
function groupRedeemableRewardsV432(rewards){
  const labels={stamp_card:'Stamp card',points:'Points'};
  const order=['stamp_card','points'];
  const groups=new Map();
  for(const reward of (Array.isArray(rewards)?rewards:[])){
    if(!reward)continue;
    const key=Object.prototype.hasOwnProperty.call(labels,reward.source)?reward.source:'other';
    if(!groups.has(key))groups.set(key,{source:key,label:labels[key]||'Rewards',rewards:[]});
    groups.get(key).rewards.push(reward);
  }
  return [...groups.values()].sort((a,b)=>{
    const ai=order.indexOf(a.source),bi=order.indexOf(b.source);
    return (ai<0?order.length:ai)-(bi<0?order.length:bi);
  });
}
