function ownerRewardJourneyV122({rewards=[],birthday=null,loyalty=null,loyaltyModel=null,asOf=null,programmes=null}={}){
  /* nestly_v567: `||'points'` invented a model that loyalty_programs.loyalty_model has never
     been allowed to hold ('classic' | 'points_tiers' | 'stamps'), purely so the `==='stamps'`
     test below would answer false. It fails closed on '' instead, and `unit` keeps its own
     explicit points default — which is a WORD for a figure, not a claim about the programme. */
  const model=normaliseLoyaltyModelV375(loyalty?.loyalty_model||loyaltyModel);
  const unit=model==='stamps'?'stamps':'points';
  /* V314 (W6 increment 1): the owner's Live/paused pill asks the SPINE. loyalty_programs.active
     stopped being the switch at v314 — it is the published setting, and the engine reads
     public.business_programmes instead. A firm that publishes an active programme without a
     spine row earns nothing while this pill said "Live"; a firm whose owner switched points on
     over a paused published version earns while it said "paused". Both are the same lie in
     opposite directions, and both are answered by the accruing spine rows. `programmes` is
     passed in rather than read from module state so this stays a pure function; a null array
     (spine unreadable) falls back to the legacy column rather than inventing a state. */
  const spineAccruingV314=Array.isArray(programmes)&&programmes.length
    ?programmes.some(row=>row&&row.active===true&&(row.kind==='points'||row.kind==='stamps'))
    :null;
  const programmeActive=spineAccruingV314===null?loyalty?.active===true:spineAccruingV314;
  const asOfMs=Number.isFinite(Date.parse(asOf||''))?Date.parse(asOf):Date.now();
  const compactNumber=value=>Number.isInteger(Number(value))?String(Number(value)):String(Number(value)).replace(/\.0+$/,'');
  const pointsRate=Math.max(0,Number(loyalty?.earn_points_per_dollar||0));
  const stampSpendCents=Math.max(0,Number(loyalty?.stamp_per_cents||0));
  const earning=!loyalty?null:model==='stamps'
    ?{model,unit,rate:stampSpendCents,availableToCustomers:programmeActive,label:`Earn 1 stamp per SGD ${(stampSpendCents/100).toFixed(2)} spent`}
    :{model,unit,rate:pointsRate,availableToCustomers:programmeActive,label:`Earn ${compactNumber(pointsRate)} points per SGD 1 spent`};
  const allRewards=Array.isArray(rewards)?rewards:[];
  const ordered=allRewards
    .filter(reward=>reward?.active!==false)
    .sort((a,b)=>Number(a.cost_points||0)-Number(b.cost_points||0)||Number(a.sort||0)-Number(b.sort||0));
  const milestones=ordered
    .map((reward,index)=>{
      const startsAt=reward.claim_available_from?Date.parse(reward.claim_available_from):null;
      const endsAt=reward.claim_available_until?Date.parse(reward.claim_available_until):null;
      /* V375: the 'not_current_model' branch went with the classic model. It hid every real
         milestone from a classic tenant, which is the business-side half of the same defect
         nestly_v375 fixed in the database reader. */
      const availability=!loyalty?'programme_unconfigured':!programmeActive?'programme_paused'
        :Number.isFinite(startsAt)&&startsAt>asOfMs?'not_started'
        :Number.isFinite(endsAt)&&endsAt<=asOfMs?'ended':'available';
      return {
        id:reward.id||String(index),name:reward.customer_name||reward.name||'Reward',
        threshold:Math.max(0,Number(reward.cost_points||0)),unit,
        additional:index?Math.max(0,Number(reward.cost_points||0)-Number(ordered[index-1]?.cost_points||0)):Math.max(0,Number(reward.cost_points||0)),
        estimatedCostCents:Math.max(0,Number(reward.estimated_cost_cents||0)),
        availability,availableToCustomers:availability==='available'
      };
    });
  const archivedRewards=allRewards.filter(reward=>reward?.active===false)
    .sort((a,b)=>Number(a.sort||0)-Number(b.sort||0)||Number(a.cost_points||0)-Number(b.cost_points||0))
    .map((reward,index)=>({
      id:reward.id||reward.reward_id||`archived-${index}`,
      name:reward.customer_name||reward.name||'Reward',threshold:Math.max(0,Number(reward.cost_points||0)),unit,
      estimatedCostCents:Math.max(0,Number(reward.estimated_cost_cents||0)),active:false
    }));
  /* V375: this synthesized a reward card reading "Points System — SGD x store credit" out of the
     programme's own redeem_points/reward_credit_cents pair. It was the last place in the browser
     that invented a reward rather than reading the owner's catalogue. */
  const birthdayReward=!birthday?null:{
    id:birthday.id||birthday.program_id||'birthday',
    active:birthday.active!==false,
    name:birthday.customer_label||'Birthday reward',
    description:birthday.customer_description||'Available in the configured birthday window.',
    value:birthday.fulfillment_kind==='discount_pct'
      ?`${Number(birthday.discount_percent||0)}% off`
      :birthday.manual_item||'Configured birthday benefit'
  };
  return {model,unit,earning,milestones,archivedRewards,birthday:birthdayReward};
}
/* v104 starts with a zero-credit structured copy assistant. It deliberately does not call a
   model from the browser or expose a provider key. The policy below is also the contract for
   a future server-side model: merchant facts are immutable inputs, never suggestions. */
const PROMOTION_COPY_POLICY_V104=Object.freeze({
  system:'You are Peekaa’s SME promotion copy assistant. Transform only the merchant-provided facts into concise Singapore English. Preserve every number, percentage, date, named item, eligibility condition and term exactly. Never invent scarcity, prices, availability, outcomes, endorsements or legal claims. Return one headline and one short message. End the message with the matching call to action from the approved CTA list. Do not add hashtags or emojis.',
  ctas:Object.freeze({book:'Book now',programme:'View offer',counter:'Show at counter'}),
  messageCtas:Object.freeze({
    book:'Book now to enjoy this offer.',
    programme:'View the offer and plan your visit.',
    counter:'Show this offer at the counter when you visit.'
  })
});
function promotionDateInputV104(value){
  if(!value)return '';
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'})
    .formatToParts(new Date(value));
  const byType=Object.fromEntries(parts.map(part=>[part.type,part.value]));
  return `${byType.year}-${byType.month}-${byType.day}`;
}
/* V324 (owner markup 2026-08-14, arrow onto the Overview "Started" column: "all date use
   dd/mm/yyyy format"). Same instant as promotionDateTextV104 — a bare yyyy-mm-dd is anchored at
   NOON Singapore, never midnight, so a date can never fall back a day on a browser west of SGT —
   and only the output pattern differs. en-GB is the locale that prints day-first with 2-digit
   parts; the timeZone stays Asia/Singapore, which is what makes the two formatters agree on which
   day it is. Applied to the Rewards & Offer tables only; the long form is still what every other
   surface renders, so this is deliberately a second formatter and not an edit to the first. */
function promotionDateShortV324(value){
  if(!value)return '';
  const instant=/^\d{4}-\d{2}-\d{2}$/.test(String(value))
    ?new Date(`${value}T12:00:00+08:00`):new Date(value);
  return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Singapore',day:'2-digit',month:'2-digit',year:'numeric'}).format(instant);
}
function promotionBoundaryV104(date,{end=false}={}){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date||'')))return null;
  return new Date(`${date}T${end?'23:59:59.999':'00:00:00.000'}+08:00`).toISOString();
}
function promotionCopyAssistV104({offerFacts,occasion,endDate,businessName,ctaKind}={}){
  const facts=String(offerFacts||'').trim(),reason=String(occasion||'').trim(),
    validUntil=promotionDateTextV104(endDate),business=String(businessName||'').trim(),
    action=PROMOTION_COPY_POLICY_V104.messageCtas[ctaKind]||
      PROMOTION_COPY_POLICY_V104.messageCtas.programme;
  if(!facts||!validUntil)return null;
  const headlineCandidate=reason?`${reason}: ${facts}`:facts,
    conciseHeadline=reason?`${reason} offer`:'Special offer',
    headline=headlineCandidate.length<=70?headlineCandidate:
      conciseHeadline.length<=70?conciseHeadline:'Special offer',
    messageStart=reason?`Celebrate ${reason} with ${facts}`:`Enjoy ${facts}`,
    messageWithBusiness=`${messageStart}${business?` at ${business}`:''}. Available until ${validUntil}. ${action}`,
    messageWithoutBusiness=`${messageStart}. Available until ${validUntil}. ${action}`,
    message=messageWithBusiness.length<=600?messageWithBusiness:messageWithoutBusiness;
  return {headline,message,ctaLabel:PROMOTION_COPY_POLICY_V104.ctas[ctaKind]||PROMOTION_COPY_POLICY_V104.ctas.programme};
}
