  function updateCurrentTimeLine(){
    if(view!=='day'||addDays(todaySg,dayOffset)!==todaySg)return;
    const timeline=routeMain.querySelector('.day-timeline'),line=routeMain.querySelector('.day-now-line');
    if(!timeline||!line)return loadCalendar();
    const rangeStart=Number(timeline.dataset.rangeStart),rangeEnd=Number(timeline.dataset.rangeEnd),hourHeight=Number(timeline.dataset.hourHeight);
    const minutes=clockMinutes(new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Asia/Singapore'}).format(new Date()));
    if(!Number.isFinite(minutes)||!Number.isFinite(rangeStart)||!Number.isFinite(rangeEnd)||!Number.isFinite(hourHeight))return;
    if(minutes<rangeStart||minutes>rangeEnd)return loadCalendar();
    line.style.top=`${(minutes-rangeStart)/60*hourHeight}px`;
    const label=line.querySelector('span');
    if(label)label.textContent=minuteClock(minutes);
  }
  calendarMinuteTimer=setInterval(()=>{
    if(!isCurrent()){clearInterval(calendarMinuteTimer);calendarMinuteTimer=null;return}
    /* v235: skip the tick while the tab is hidden. updateCurrentTimeLine() is not always cheap —
       once "now" moves outside the rendered range it falls through to loadCalendar(), and since a
       reload does not necessarily bring the range back over "now", that repeats EVERY minute for
       as long as the view stays open. A shop tablet parked on Appointments overnight was therefore
       re-querying the calendar 60x an hour with nobody looking at it. The line is repainted on the
       next tick after the tab is shown again, so nothing is stale by more than a minute. */
    if(globalThis.document?.visibilityState==='hidden')return;
    updateCurrentTimeLine();
  },60000);
