  function weekStart(offset=0){
    const now=new Date(Date.now()+8*3600000),day=(now.getUTCDay()+6)%7;
    const monday=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()-day+offset*7));
    return monday.toISOString().slice(0,10);
  }
  const addDays=(date,days)=>{const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)};
  function eventParts(iso){
    const d=new Date(new Date(iso).getTime()+8*3600000);
    return {date:d.toISOString().slice(0,10),minutes:d.getUTCHours()*60+d.getUTCMinutes()};
  }
