/* nestly_v679 — Customer intelligence gets three more evidence-safe panels: the lifecycle funnel
   (get_ci_funnel_conversion_v1, v673), demographics (get_ci_demographics_v1, v674) and weekday
   behaviour (get_ci_daypart_v1, v675). Each renderer below is a pure TOP-LEVEL function — same
   posture as recoveryReportHtmlV550 — so a test can extract this block and EXECUTE it against a
   fixture shaped exactly like the deployed RPC's own output, without touching the DOM or any
   customerIntelligencePage closure state. Error/empty wiring (ciFunnelConversionMarkupV679 and
   its two siblings) stays inside customerIntelligencePage, reusing its existing ciQuietErrorV650
   idiom exactly, so a failed RPC withholds the panel the same way every other section on this
   page already does — never a zero-stuffed table pretending to be a real answer. */
function ciMeasuredSinceInlineV679(observedSince){
  return observedSince
    ?`<p class="muted small" style="margin-top:10px">Measured since ${esc(walletDate(observedSince,true))}</p>`
    :'';
}
/* nestly_v734 (check 97): every CI reader's shared envelope (app.ci_envelope_v680, v722) now
   carries a top-level `freshness` block -- {data_as_of, observed_since, generated_at, age_hours,
   stale, note}. v722 shipped that disclosure and nothing on this page ever read it. This is the
   ONE renderer, reused by every CI panel below (funnelConversionPanelHtmlV679,
   demographicsPanelHtmlV679, behaviourPanelHtmlV679, opportunitiesPanelHtmlV685) and the v650
   markups (categoryMixMarkupV650, acquisitionMarkupV650, funnelMarkupV650,
   contactabilityMarkupV650), plus the platform-console.js consultant brief's own copy.
   Age is always the server's own age_hours -- never recomputed from the client clock, which
   cannot be trusted and could silently drift from whatever staleness rule the server enforces.
   Disclosure only: a stale payload still renders in full underneath this caption, it is never a
   reason to withhold the panel. A payload from a reader that predates v722 (or a reader that
   never carries freshness, like an older cached fixture) has no `freshness` key at all -- this
   renders nothing, not a crash, not a fabricated "data as of never". */
function ciFreshnessCaptionHtmlV734(payload){
  const freshness=payload&&typeof payload==='object'?payload.freshness:null;
  /* get_ci_opportunities_v1 keeps its OWN bespoke `freshness` shape (observed_since_min etc.,
     v680/v688) that app.ci_envelope_v680 deliberately passes through untouched (v722 -- see the
     "reader that already sets freshness" branch). That shape has no `stale` key at all, so this
     guard is what stops this shared helper from misreading it and fabricating "age unknown". */
  if(!freshness||typeof freshness!=='object'||!('stale' in freshness))return '';
  const dataAsOfText=freshness.data_as_of?walletDate(freshness.data_as_of,true):null;
  const ageHours=(freshness.age_hours===null||freshness.age_hours===undefined)?null:Number(freshness.age_hours);
  const ageText=ageHours===null?'age unknown'
    :ageHours<1?'under an hour old'
    :`${ageHours.toFixed(1)} hour${ageHours===1?'':'s'} old`;
  const freshLine=`Data as of ${dataAsOfText||'no recorded sale yet'} · ${ageText}`;
  const staleLine=freshness.stale
    ?`<p class="muted small ci-freshness-stale-v734" role="status">Data may be out of date — last sale ${esc(dataAsOfText||'never recorded')}.${freshness.note?` ${esc(String(freshness.note))}`:''}</p>`
    :'';
  return `<p class="muted small ci-freshness-caption-v734">${esc(freshLine)}</p>${staleLine}`;
}
function ciEmptyPanelV679(headingId,eyebrow,title,message){
  return `<section class="revenue-truth-section" aria-labelledby="${headingId}">
    <div class="revenue-truth-section-head"><div><span class="revenue-truth-eyebrow">${esc(eyebrow)}</span>
    <h2 id="${headingId}">${esc(title)}</h2></div></div>
    <div class="empty">${esc(message)}</div></section>`;
}
/* A rate that always carries its own counts — the app.rate_block_v1 shape (numerator/denominator/
   pct). pct is null when the denominator is zero OR the evidence floor was not cleared; this
   NEVER renders as 0.0%, only as the page's own not-enough-data idiom. */
function ciRateBlockV679(block){
  const b=block&&typeof block==='object'?block:{};
  const num=Number(b.numerator)||0,den=Number(b.denominator)||0;
  const pctText=(b.pct===null||b.pct===undefined)?'Not enough data yet':`${Number(b.pct).toFixed(1)}%`;
  return {num,den,pctText};
}
/* app.subgroup_evidence_v1 shape: {n,floor,status}. Only ever used for a caption next to a value
   the SQL has already nulled out below its own floor — never to re-derive the null itself. */
function ciEvidenceInsufficientV679(evidence){
  const ev=evidence&&typeof evidence==='object'?evidence:{};
  return ev.status==='insufficient';
}
function ciEvidenceCaptionV679(evidence){
  const ev=evidence&&typeof evidence==='object'?evidence:{};
  if(ev.status!=='insufficient')return '';
  const floor=Number(ev.floor)||5;
  return `Not enough data yet (fewer than ${floor}).`;
}

/* 1. get_ci_funnel_conversion_v1 (nestly_v673) — 1st->2nd->3rd visit conversion, maturity-gated. */
function funnelConversionPanelHtmlV679(payload){
  if(!payload||typeof payload!=='object')
    return ciEmptyPanelV679('ciFunnelConversionHeadingV679','How customers return','Retention funnel','Run this report to load the retention funnel.');
  const p=payload;
  const windowDays=Number(p.window_days)||0;
  const stage1=ciRateBlockV679(p.stage_1_to_2);
  const stage2=ciRateBlockV679(p.stage_2_to_3);
  const immature=p.immature&&typeof p.immature==='object'?p.immature:{};
  const firstImmature=Number(immature.first_stage)||0,secondImmature=Number(immature.second_stage)||0;
  const bottleneckLabel=p.bottleneck==='first_to_second'?'First to second visit'
    :p.bottleneck==='second_to_third'?'Second to third visit':null;
  const bottleneckLine=bottleneckLabel
    ?`Bottleneck: <b>${esc(bottleneckLabel)}</b>`
    :(ciEvidenceInsufficientV679(p.evidence)
      ?`${ciEvidenceCaptionV679(p.evidence)} No bottleneck can be named yet.`
      :'No bottleneck — the two stages convert about equally.');
  return `<section class="revenue-truth-section" aria-labelledby="ciFunnelConversionHeadingV679">
    <div class="revenue-truth-section-head"><div><span class="revenue-truth-eyebrow">How customers return</span>
    <h2 id="ciFunnelConversionHeadingV679">Retention funnel</h2></div></div>
    <p class="muted small">Each stage is measured over a ${windowDays}-day window from the customer's own prior visit, based on ${esc(p.time_basis||'sale_occurred_at')}.</p>
    <div class="revenue-truth-metrics">
      <article class="revenue-truth-metric"><span>First to second visit</span><strong>${stage1.num} of ${stage1.den} returned (${stage1.pctText})</strong></article>
      <article class="revenue-truth-metric"><span>Second to third visit</span><strong>${stage2.num} of ${stage2.den} returned (${stage2.pctText})</strong></article>
    </div>
    <p class="muted small" style="margin-top:10px">${firstImmature} customer${firstImmature===1?'':'s'} too recent to judge for the first stage; ${secondImmature} too recent for the second.</p>
    <p class="muted small">${bottleneckLine}</p>
    ${ciMeasuredSinceInlineV679(p.observed_since)}
    ${ciFreshnessCaptionHtmlV734(p)}
  </section>`;
}

/* 2. get_ci_demographics_v1 (nestly_v674) — (age_band x gender) revenue/frequency/ATV grid. */
const CI_AGE_BAND_LABELS_V679={under_20:'Under 20','20_24':'20–24','25_30':'25–30',
  '31_40':'31–40','41_50':'41–50','51_plus':'51+'};
function demographicsPanelHtmlV679(payload){
  if(!payload||typeof payload!=='object')
    return ciEmptyPanelV679('ciDemographicsHeadingV679','Who they are','Demographics','Run this report to load demographics.');
  const p=payload;
  const cells=Array.isArray(p.cells)?p.cells:[];
  const unclassified=p.unclassified&&typeof p.unclassified==='object'?p.unclassified:{};
  const coverage=p.coverage&&typeof p.coverage==='object'?p.coverage:{};
  const rows=cells.map(cell=>{
    const atvText=(cell.atv_cents===null||cell.atv_cents===undefined)
      ?(ciEvidenceCaptionV679(cell.evidence)||'Not enough data yet')
      :esc(money(cell.atv_cents));
    const genderLabel=cell.gender==='female'?'Female':cell.gender==='male'?'Male':cell.gender==='other'?'Other':(cell.gender||'—');
    return `<tr><td data-label="Age band">${esc(CI_AGE_BAND_LABELS_V679[cell.age_band]||cell.age_band||'—')}</td><td data-label="Gender">${esc(genderLabel)}</td><td data-label="Customers">${Number(cell.customers)||0}</td><td data-label="Revenue">${esc(money(cell.revenue_cents))}</td><td data-label="Cell visits">${Number(cell.visits)||0}</td><td data-label="Average transaction value">${atvText}</td></tr>`;
  }).join('');
  const unclassifiedCustomers=Number(unclassified.customers)||0,unclassifiedRevenue=Number(unclassified.revenue_cents)||0;
  const demCoverage=ciRateBlockV679(coverage.demographics);
  const revCoverage=ciRateBlockV679(coverage.revenue);
  return `<section class="revenue-truth-section" aria-labelledby="ciDemographicsHeadingV679">
    <div class="revenue-truth-section-head"><div><span class="revenue-truth-eyebrow">Who they are</span>
    <h2 id="ciDemographicsHeadingV679">Demographics</h2></div></div>
    ${(cells.length||unclassifiedCustomers)?`<div class="cui-table-wrap" role="region" aria-label="Demographics"><table class="cui-table"><thead><tr><th>Age band</th><th>Gender</th><th>Customers</th><th>Revenue</th><th>Cell visits</th><th>Average transaction value</th></tr></thead><tbody>${rows}<tr><td data-label="Age band">Unclassified</td><td data-label="Gender">—</td><td data-label="Customers">${unclassifiedCustomers}</td><td data-label="Revenue">${esc(money(unclassifiedRevenue))}</td><td data-label="Cell visits">—</td><td data-label="Average transaction value">—</td></tr></tbody></table></div>`
      :'<div class="empty">No identified customers in this scope yet.</div>'}
    <p class="muted small" style="margin-top:10px">Demographics known for ${demCoverage.num} of ${demCoverage.den} identified customers (${demCoverage.pctText}).</p>
    <p class="muted small">Revenue explained by known demographics: ${esc(money(revCoverage.num))} of ${esc(money(revCoverage.den))} (${revCoverage.pctText}).</p>
    ${ciMeasuredSinceInlineV679(p.observed_since)}
    ${ciFreshnessCaptionHtmlV734(p)}
  </section>`;
}

/* 3. get_ci_daypart_v1 (nestly_v675) — weekday behaviour with an honest exposure denominator;
   busiest (a raw count) and most-valuable (evidence-gated) are reported separately (check 36). */
function behaviourPanelHtmlV679(payload){
  if(!payload||typeof payload!=='object')
    return ciEmptyPanelV679('ciBehaviourHeadingV679','When customers come in','Weekday behaviour','Run this report to load weekday behaviour.');
  const p=payload;
  const weekdays=Array.isArray(p.weekdays)?p.weekdays:[];
  const busiest=p.busiest_weekday&&typeof p.busiest_weekday==='object'?p.busiest_weekday:null;
  const mostValuable=p.most_valuable_weekday&&typeof p.most_valuable_weekday==='object'?p.most_valuable_weekday:null;
  const rows=weekdays.map(weekday=>{
    const perVisit=(weekday.revenue_per_visit_cents===null||weekday.revenue_per_visit_cents===undefined)
      ?(ciEvidenceCaptionV679(weekday.evidence)||'Not enough data yet')
      :esc(money(weekday.revenue_per_visit_cents));
    const occurrence=ciRateBlockV679(weekday.visits_per_occurrence);
    return `<tr><td data-label="Weekday">${esc(weekday.label||'')}</td><td data-label="Weekday visits">${Number(weekday.visits)||0}</td><td data-label="Revenue">${esc(money(weekday.revenue_cents))}</td><td data-label="Revenue per visit">${perVisit}</td><td data-label="Occurrences in range">${Number(weekday.weekday_occurrences)||0}</td><td data-label="Visited on">${occurrence.num} of ${occurrence.den} (${occurrence.pctText})</td></tr>`;
  }).join('');
  const busiestLine=busiest
    ?`<b>${esc(busiest.label||'')}</b> — ${Number(busiest.visits)||0} visits`
    :'Not enough data yet';
  const mostValuableLine=mostValuable
    ?`<b>${esc(mostValuable.label||'')}</b> — ${esc(money(mostValuable.revenue_per_visit_cents))} per visit`
    :'Not enough data yet — no weekday has cleared the evidence floor.';
  return `<section class="revenue-truth-section" aria-labelledby="ciBehaviourHeadingV679">
    <div class="revenue-truth-section-head"><div><span class="revenue-truth-eyebrow">When customers come in</span>
    <h2 id="ciBehaviourHeadingV679">Weekday behaviour</h2></div></div>
    <div class="revenue-truth-metrics">
      <article class="revenue-truth-metric"><span>Busiest day (by visits)</span><strong>${busiestLine}</strong></article>
      <article class="revenue-truth-metric"><span>Most valuable day (by revenue per visit)</span><strong>${mostValuableLine}</strong></article>
    </div>
    ${weekdays.length?`<div class="cui-table-wrap" role="region" aria-label="Weekday behaviour"><table class="cui-table"><thead><tr><th>Weekday</th><th>Weekday visits</th><th>Revenue</th><th>Revenue per visit</th><th>Occurrences in range</th><th>Visited on</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">No weekday activity in this scope yet.</div>'}
    <p class="muted small" style="margin-top:10px">Time basis: ${esc(p.time_basis||'sale_occurred_at')}.</p>
    <p class="muted small">${esc(p.basis_note||'')}</p>
    ${ciMeasuredSinceInlineV679(p.observed_since)}
    ${ciFreshnessCaptionHtmlV734(p)}
  </section>`;
}

/* nestly_v771 — the Owner brief, the first thing Customer intelligence now shows.
   Owner ruling: this page must be straightforward for an SME owner, so the brief answers six
   plain questions — how the period went, who to call, what has been paid for and not used, who
   matters most, which service brings people back, and what Peekaa is refusing to guess at — in
   names, dollars and days. No basis points, no evidence classes, no minor-unit vocabulary, and
   (standing analytics ruling, v768) no channel named WhatsApp anywhere on it: the bring-back
   action here is a phone call and a link to the customer's own record.

   It is a PURE top-level function taking ONE plain object so a test can execute it against
   fixtures shaped exactly like the RPCs' real payloads (tests/business-ui/v771-owner-brief.test.mjs),
   the same posture as funnelConversionPanelHtmlV679 and its siblings above. It is deliberately
   self-contained — it reaches for nothing but esc/money/CUI/S, which every harness already
   stubs — because the closure slice that feeds it is extracted and executed by other test files.
   The two status vocabularies it inlines (bring-back tones, limit sentences) are local copies for
   that reason; ATTENTION_STATUS_V548 remains the authority the Bring-back module itself reads. */
function ownerBriefHtmlV771(brief){
  const briefV771=(brief&&typeof brief==='object')?brief:{};
  /* Number(null) is 0 and Number('') is 0, so a bare Number.isFinite check would silently turn
     "this business has never recorded that" into a confident zero — a null per-session price would
     become a free session, a null last visit would become "0 days ago", and a withheld repeat rate
     would become "(0%)". Absence has to stay absent all the way to the markup. */
  const finiteV771=value=>{
    if(value===null||value===undefined||typeof value==='boolean')return null;
    if(typeof value==='string'&&!value.trim())return null;
    const parsed=Number(value);
    return Number.isFinite(parsed)?parsed:null;
  };
  const countV771=value=>{const parsed=finiteV771(value);return parsed===null?0:Math.round(parsed);};
  const nameV771=value=>{const text=String(value==null?'':value).trim();return text||'Customer';};
  const daysAgoV771=value=>{const parsed=finiteV771(value);return parsed===null?null:`${Math.round(parsed)} days ago`;};
  const objectV771=value=>(value&&typeof value==='object'&&!Array.isArray(value))?value:null;
  const periodDaysV771=Math.max(1,countV771(briefV771.periodDays)||1);
  const canOpenV771=briefV771.canOpenCustomers===true;
  const openCellV771=clientId=>{
    const id=String(clientId==null?'':clientId);
    if(!canOpenV771||!id)return '';
    return `<a class="btn ghost sm" href="#/client/${encodeURIComponent(id)}">Open</a>`;
  };
  const headV771=(iconName,titleId,title,line)=>`<div class="cui-card-head" style="display:flex;gap:10px;align-items:flex-start;margin-top:4px">${CUI.icon(iconName,{size:22})}<div><h3 id="${titleId}" style="font-size:15px;margin:0">${esc(title)}</h3><p class="muted small" style="margin-top:2px">${esc(line)}</p></div></div>`;
  const errorRowV771=(label,message)=>`<div class="err" role="status">${esc(label)} ${esc(message||'Try running the report again.')}</div>`;

  /* ---- A. This period at a glance ------------------------------------------------------- */
  const truthNowV771=objectV771(briefV771.truth),truthPrevV771=objectV771(briefV771.truthPrev);
  const lifeNowV771=objectV771(briefV771.lifecycle),lifePrevV771=objectV771(briefV771.lifecyclePrev);
  const revenueNowV771=finiteV771(objectV771(truthNowV771?.totals)?.known_revenue_minor);
  const revenuePrevV771=finiteV771(objectV771(truthPrevV771?.totals)?.known_revenue_minor);
  const buyersNowV771=finiteV771(objectV771(lifeNowV771?.metrics)?.transacting_identified_customers);
  const buyersPrevV771=finiteV771(objectV771(lifePrevV771?.metrics)?.transacting_identified_customers);
  const joinersNowV771=finiteV771(objectV771(lifeNowV771?.metrics)?.new_customers);
  const joinersPrevV771=finiteV771(objectV771(lifePrevV771?.metrics)?.new_customers);
  /* A share only means something against a denominator that exists and is above zero. When the
     earlier window has none, the tile says so rather than printing a growth figure from nothing. */
  const compareV771=(now,before)=>{
    if(now===null||before===null||before<=0)return 'no earlier data to compare';
    const change=Math.round((now-before)/before*100);
    if(!Number.isFinite(change))return 'no earlier data to compare';
    if(change===0)return `vs the previous ${periodDaysV771} days: no change`;
    return `vs the previous ${periodDaysV771} days: ${change>0?'+':'−'}${Math.abs(change)}%`;
  };
  const tileV771=(label,value,caption)=>`<article class="revenue-truth-metric"><span>${esc(label)}</span><strong>${esc(value)}</strong><span class="muted small" style="display:block;margin-top:4px">${esc(caption)}</span></article>`;
  const glanceV771=`<section class="ci-brief-glance-v771" aria-labelledby="ciBriefGlanceTitleV771" style="margin-top:14px">
    ${headV771('reports','ciBriefGlanceTitleV771','This period at a glance','How the last '+periodDaysV771+' days went, against the '+periodDaysV771+' days before them.')}
    <div class="revenue-truth-metrics">
      ${tileV771('Revenue recorded',revenueNowV771===null?'—':money(revenueNowV771),compareV771(revenueNowV771,revenuePrevV771))}
      ${tileV771('Customers who bought',buyersNowV771===null?'—':String(buyersNowV771),compareV771(buyersNowV771,buyersPrevV771))}
      ${tileV771('New customers',joinersNowV771===null?'—':String(joinersNowV771),compareV771(joinersNowV771,joinersPrevV771))}
    </div>
  </section>`;

  /* ---- B. Customers to bring back -------------------------------------------------------- */
  /* Local copy of the bring-back vocabulary, for the self-containment reason in the header
     comment. Labels and tones must stay identical to ATTENTION_STATUS_V548 — a status coloured
     one way here and another way in the Bring-back module would teach two habits. */
  const BRING_BACK_STATUS_V771={
    due:{label:'Due back',tone:'#F0A35B'},
    overdue:{label:'Overdue',tone:'#C24135'},
    slipping:{label:'Slipping away',tone:'#8E2F26'}
  };
  const attentionV771=objectV771(briefV771.attention);
  const attentionErrorV771=String(briefV771.attentionError||'').trim();
  const attentionRowsV771=Array.isArray(attentionV771?.rows)?attentionV771.rows.filter(row=>row&&typeof row==='object'):[];
  const bringBackPillV771=statusKey=>{
    const status=BRING_BACK_STATUS_V771[String(statusKey||'')];
    if(!status)return '';
    return `<span class="pill" style="background:${status.tone}1A;color:${status.tone};font-weight:700;white-space:nowrap">${esc(status.label)}</span>`;
  };
  /* nestly_v771 (owner acceptance): ONE cadence authority, and it is the server's. This block
     used to derive its own "quiet lately" verdict in the browser, comparing
     days_since_last_purchase against average_days_between_purchases — a second opinion on the
     question get_attention_list_v548 already answers, and a worse one: it called a customer with
     a 1.3-day rhythm quiet three days after a visit. Block D's Note column now repeats the status
     the bring-back reader gave that exact client, or says nothing at all. */
  const bringBackStatusByClientV771=new Map();
  attentionRowsV771.forEach(row=>{
    if(row.client_id==null)return;
    const key=String(row.status||'');
    if(BRING_BACK_STATUS_V771[key])bringBackStatusByClientV771.set(String(row.client_id),key);
  });
  let bringBackV771='';
  if(attentionV771||attentionErrorV771){
    const attentionSummaryV771=objectV771(attentionV771?.summary)||{};
    const fadingV771=countV771(attentionSummaryV771.overdue)+countV771(attentionSummaryV771.slipping);
    const atRiskV771=countV771(attentionSummaryV771.monthly_at_risk_cents);
    const oneTimeV771=countV771(attentionSummaryV771.one_time_count);
    /* nestly_v771 (375px check): the responsive table turns every td into a two-column grid with
       right-aligned content, so two sibling links in one cell become two grid items and "Open"
       drops onto its own row on the left — which reads as a second customer. One inline-flex
       wrapper makes the pair a single grid item. Two .btn.sm links are about 120px together
       against roughly 187px of second column at 375px, so nothing overflows. */
    const bringBackRowV771=row=>{
      const cadence=finiteV771(row.cadence_days);
      const digits=String(row.phone==null?'':row.phone).replace(/\D/g,'');
      const call=digits?`<a class="btn ghost sm" href="tel:${digits}">Call</a>`:'';
      const open=openCellV771(row.client_id);
      return `<tr><td data-label="Customer"><b>${esc(nameV771(row.full_name))}</b></td>
        <td data-label="Usually comes every">${cadence===null?'—':esc(Math.round(cadence)+' days')}</td>
        <td data-label="Last visit">${esc(daysAgoV771(row.last_visit_days)||'—')}</td>
        <td data-label="Status">${bringBackPillV771(row.status)||bringBackPillV771('due')}</td>
        <td data-label="Action"><span class="ci-brief-actions-v771" style="display:inline-flex;gap:6px;white-space:nowrap;justify-content:flex-end">${call}${open}</span></td></tr>`;
    };
    bringBackV771=`<section class="ci-brief-bringback-v771" aria-labelledby="ciBriefBringBackTitleV771" style="margin-top:18px">
      ${headV771('phone','ciBriefBringBackTitleV771','Customers to bring back','Each person judged against their own visit rhythm, not a fixed rule.')}
      ${attentionErrorV771?errorRowV771('Customers to bring back could not load.',attentionErrorV771):`
      ${fadingV771>0?`<p style="margin:8px 0 2px"><b>${fadingV771} customer${fadingV771===1?'':'s'} overdue</b> · about ${esc(money(atRiskV771))} a month of regular spend at risk</p>`:''}
      ${attentionRowsV771.length?`<div class="cui-table-wrap" role="region" aria-label="Customers to bring back"><table class="cui-table" data-responsive="true"><thead><tr><th>Customer</th><th>Usually comes every</th><th>Last visit</th><th>Status</th><th>Action</th></tr></thead><tbody>${attentionRowsV771.map(bringBackRowV771).join('')}</tbody></table></div>`
        :'<div class="empty">Nobody is overdue against their own visit rhythm right now.</div>'}
      ${oneTimeV771>0?`<p class="muted small" style="margin-top:10px">${oneTimeV771} customer${oneTimeV771===1?'':'s'} visited once in the last year and never came back.</p>`:''}`}
    </section>`;
  }

  /* ---- C. Prepaid sessions still unused --------------------------------------------------- */
  const peopleV771=Array.isArray(briefV771.customers)?briefV771.customers.filter(record=>record&&typeof record==='object'):[];
  const peopleByIdV771=new Map();
  peopleV771.forEach(record=>{if(record.client_id!=null)peopleByIdV771.set(String(record.client_id),record);});
  const packagesV771=Array.isArray(briefV771.packages)?briefV771.packages:null;
  const packagesErrorV771=String(briefV771.packagesError||'').trim();
  let unusedV771='';
  if(packagesV771||packagesErrorV771){
    const heldV771=new Map();
    (packagesV771||[]).forEach(row=>{
      if(!row||typeof row!=='object')return;
      const key=String(row.client_id==null?'':row.client_id);
      const left=countV771(row.remaining);
      if(!key||left<=0)return;
      let held=heldV771.get(key);
      if(!held){
        const record=peopleByIdV771.get(key)||null;
        held={key,name:nameV771(record?.full_name),lastVisit:finiteV771(record?.days_since_last_purchase),
          sessions:0,plans:[],valueCents:0,valueKnown:true};
        heldV771.set(key,held);
      }
      held.sessions+=left;
      const planName=String(row.plan_name_snapshot==null?'':row.plan_name_snapshot).trim();
      if(planName&&held.plans.indexOf(planName)<0)held.plans.push(planName);
      /* A value is shown only when EVERY row behind it carries a per-session list price. One
         missing snapshot makes the customer's total a guess, so that row prints a dash instead. */
      const unit=finiteV771(row.list_unit_cents_snapshot);
      if(unit===null)held.valueKnown=false;else held.valueCents+=left*unit;
    });
    /* Longest-unseen first; a customer with no visit on record is the most urgent of all. */
    const unusedRowsV771=[...heldV771.values()].sort((first,second)=>
      (second.lastVisit===null?Infinity:second.lastVisit)-(first.lastVisit===null?Infinity:first.lastVisit));
    const holdersV771=unusedRowsV771.length;
    const sessionsV771=unusedRowsV771.reduce((total,held)=>total+held.sessions,0);
    const allValuedV771=holdersV771>0&&unusedRowsV771.every(held=>held.valueKnown);
    const unusedValueV771=unusedRowsV771.reduce((total,held)=>total+held.valueCents,0);
    const headlineV771=`${holdersV771} customer${holdersV771===1?'':'s'} hold${holdersV771===1?'s':''} ${sessionsV771} unused session${sessionsV771===1?'':'s'}`
      +(allValuedV771?` worth about ${money(unusedValueV771)}`:'');
    unusedV771=`<section class="ci-brief-unused-v771" aria-labelledby="ciBriefUnusedTitleV771" style="margin-top:18px">
      ${headV771('packages','ciBriefUnusedTitleV771','Prepaid sessions still unused','Work these customers have already paid for and not yet taken.')}
      ${packagesErrorV771?errorRowV771('Prepaid sessions still unused could not load.',packagesErrorV771):`
      ${holdersV771?`<p style="margin:8px 0 2px"><b>${esc(headlineV771)}</b></p>
      <div class="cui-table-wrap" role="region" aria-label="Prepaid sessions still unused"><table class="cui-table" data-responsive="true"><thead><tr><th>Customer</th><th>Sessions left</th><th>Plan</th><th>Last visit</th><th>Value</th>${canOpenV771?'<th>Action</th>':''}</tr></thead><tbody>${unusedRowsV771.map(held=>
        `<tr><td data-label="Customer"><b>${esc(held.name)}</b></td>
        <td data-label="Sessions left">${held.sessions}</td>
        <td data-label="Plan">${esc(held.plans.join(', ')||'—')}</td>
        <td data-label="Last visit">${esc(daysAgoV771(held.lastVisit)||'no visit recorded')}</td>
        <td data-label="Value">${held.valueKnown?esc(money(held.valueCents)):'—'}</td>
        ${canOpenV771?`<td data-label="Action">${openCellV771(held.key)}</td>`:''}</tr>`).join('')}</tbody></table></div>`
        :'<div class="empty">Every prepaid session has been used.</div>'}`}
    </section>`;
  }

  /* ---- D. Your top customers -------------------------------------------------------------- */
  const identifiedTotalV771=finiteV771(objectV771(briefV771.summary)?.net_revenue_cents);
  const shareBaseV771=(identifiedTotalV771!==null&&identifiedTotalV771>0)?identifiedTotalV771:null;
  const earnersV771=peopleV771
    .filter(record=>{const earned=finiteV771(record.net_revenue_cents);return earned!==null&&earned>0;})
    .sort((first,second)=>Number(second.net_revenue_cents)-Number(first.net_revenue_cents))
    .slice(0,10);
  const shareTextV771=amount=>shareBaseV771===null?'—':`${Math.round(amount/shareBaseV771*100)}% of revenue`;
  const leadCountV771=Math.min(3,earnersV771.length);
  const leadShareV771=earnersV771.slice(0,leadCountV771).reduce((total,record)=>total+Number(record.net_revenue_cents||0),0);
  const topLineV771=(leadCountV771>0&&shareBaseV771!==null)
    ?`<p style="margin:8px 0 2px">Your top ${leadCountV771} customer${leadCountV771===1?'':'s'} are ${Math.round(leadShareV771/shareBaseV771*100)}% of revenue.</p>`
    :'';
  /* V522's ruling holds here: `visit_count` on this page counts only visits that charged an
     amount, so the column says "Paid visits". A bare "Visits" would mean the Dashboard's number,
     which also counts zero-price visits such as package sessions, and the two would disagree. */
  const topCustomersV771=`<section class="ci-brief-top-v771" aria-labelledby="ciBriefTopTitleV771" style="margin-top:18px">
    ${headV771('star','ciBriefTopTitleV771','Your top customers','The people the period actually rested on.')}
    ${topLineV771}
    ${earnersV771.length?`<div class="cui-table-wrap" role="region" aria-label="Your top customers"><table class="cui-table" data-responsive="true"><thead><tr><th>Customer</th><th>Revenue</th><th>Share</th><th>Paid visits</th><th>Last visit</th><th>Note</th>${canOpenV771?'<th>Action</th>':''}</tr></thead><tbody>${earnersV771.map(record=>{
      const since=finiteV771(record.days_since_last_purchase);
      return `<tr><td data-label="Customer"><b>${esc(nameV771(record.full_name))}</b></td>
        <td data-label="Revenue"><b>${esc(money(record.net_revenue_cents))}</b></td>
        <td data-label="Share">${esc(shareTextV771(Number(record.net_revenue_cents)))}</td>
        <td data-label="Paid visits">${countV771(record.visit_count)}</td>
        <td data-label="Last visit">${esc(daysAgoV771(since)||'—')}</td>
        <td data-label="Note">${bringBackPillV771(bringBackStatusByClientV771.get(String(record.client_id)))}</td>
        ${canOpenV771?`<td data-label="Action">${openCellV771(record.client_id)}</td>`:''}</tr>`;
    }).join('')}</tbody></table></div>
    <p class="muted small" style="margin-top:10px">Shares are of revenue from known customers. Walk-in sales with no name attached are not included.</p>`
      :'<div class="empty">No identified customer revenue in this period yet.</div>'}
  </section>`;

  /* ---- E. Which service brings people back ------------------------------------------------ */
  const serviceBundleV771=objectV771(briefV771.services);
  const servicesErrorV771=String(briefV771.servicesError||'').trim();
  const serviceRowsV771=Array.isArray(serviceBundleV771?.services)
    ?serviceBundleV771.services.filter(row=>row&&typeof row==='object').slice()
      .sort((first,second)=>countV771(second.buyers)-countV771(first.buyers))
    :[];
  const servicesV771=`<section class="ci-brief-services-v771" aria-labelledby="ciBriefServicesTitleV771" style="margin-top:18px">
    ${headV771('services','ciBriefServicesTitleV771','Which service brings people back','What people buy first, and what they come back for.')}
    ${servicesErrorV771?errorRowV771('Which service brings people back could not load.',servicesErrorV771):`
    ${serviceRowsV771.length?`<div class="cui-table-wrap" role="region" aria-label="Which service brings people back"><table class="cui-table" data-responsive="true"><thead><tr><th>Service</th><th>Customers who bought it</th><th>Bought it again</th><th>First-time customers it brought in</th><th>Revenue</th></tr></thead><tbody>${serviceRowsV771.map(row=>{
      const again=objectV771(row.repeat_rate)||{};
      const share=finiteV771(again.pct);
      const againText=`${countV771(again.numerator)} of ${countV771(again.denominator)}`
        +(share===null?' — too few to say':` (${Math.round(share)}%)`);
      return `<tr><td data-label="Service"><b>${esc(nameV771(row.service_name))}</b></td>
        <td data-label="Customers who bought it">${countV771(row.buyers)}</td>
        <td data-label="Bought it again">${esc(againText)}</td>
        <td data-label="First-time customers it brought in">${countV771(row.gateway_count)}</td>
        <td data-label="Revenue">${esc(money(row.revenue_cents))}</td></tr>`;
    }).join('')}</tbody></table></div>`
      :'<div class="empty">No service sales in this period yet.</div>'}`}
  </section>`;

  /* ---- F. What Peekaa cannot tell you yet -------------------------------------------------- */
  /* The server abstains in its own vocabulary ("below the sample floor of 5", "mix-adjusted
     index"). An owner should not have to learn it, so each generator gets one plain sentence
     naming the finding that is missing and what would make it appear.

     nestly_v771 (owner acceptance): two of those abstentions are not missing findings at all.
     The loyalty-cannibalisation and staff-mix generators abstain BECAUSE they looked and found
     nothing over the bar — that is a clean bill of health, and filing it under "cannot tell you
     yet" reads as a gap in the product rather than a result. They get their own list and their
     own wording; everything else keeps the "here is what would make this appear" shape. */
  const CLEARED_SENTENCES_V771={
    loyalty_cannibalisation_gap:'Your loyalty rewards are not paying customers who would have come anyway.',
    staff_mix_underperformance:'No staff member’s customers return noticeably less than the others’.'
  };
  const LIMIT_SENTENCES_V771={
    funnel_bottleneck:'Whether more customers are lost after the first visit or after the second — needs more customers to have reached a second and third visit.',
    lapsed_regulars:'Which regulars are overdue against their own rhythm — needs customers with at least three visits so a rhythm exists.',
    package_leakage:'Which package plans are being left unused — needs at least five sales of the same plan.',
    gateway_followthrough:'Which first service best turns a walk-in into a regular — needs more customers to have reached a second visit.',
    no_discount_reminder:'Whether a plain reminder works as well as a discount — needs more contacted customers.',
    campaigns:'Whether a campaign brought people back — needs a campaign old enough to measure.'
  };
  const limitsOrderV771=[],limitsSeenV771=new Map();
  (Array.isArray(briefV771.abstentions)?briefV771.abstentions:[]).forEach(item=>{
    if(!item||typeof item!=='object')return;
    const generator=String(item.generator==null?'':item.generator);
    const key=generator.split(':')[0].trim();
    if(!key)return;
    if(!limitsSeenV771.has(key)){
      let sentence=CLEARED_SENTENCES_V771[key]||LIMIT_SENTENCES_V771[key];
      if(!sentence){
        const plain=String(item.reason==null?'':item.reason).replace(/_/g,' ').replace(/:\s*$/,'').trim()
          ||key.replace(/_/g,' ');
        sentence=plain.charAt(0).toUpperCase()+plain.slice(1);
      }
      limitsSeenV771.set(key,{key,sentence,count:0});
      limitsOrderV771.push(key);
    }
    limitsSeenV771.get(key).count+=1;
  });
  const isClearedV771=key=>Object.prototype.hasOwnProperty.call(CLEARED_SENTENCES_V771,key);
  const limitsListV771=(label,keys)=>keys.length
    ?`<p class="small" style="margin:12px 0 2px"><b>${esc(label)}</b></p>
      <ul style="margin:0;padding-left:20px">${keys.map(key=>{
        const entry=limitsSeenV771.get(key);
        const plans=(key==='package_leakage'&&entry.count>1)?` (${entry.count} plans)`:'';
        return `<li style="margin:4px 0">${esc(entry.sentence+plans)}</li>`;
      }).join('')}</ul>`
    :'';
  const limitsV771=limitsOrderV771.length
    ?`<section class="ci-brief-limits-v771" aria-labelledby="ciBriefLimitsTitleV771" style="margin-top:18px">
      ${headV771('info','ciBriefLimitsTitleV771','What Peekaa cannot tell you yet','What is still waiting on evidence, and what has already been checked and come back clean.')}
      ${limitsListV771('Not enough evidence yet',limitsOrderV771.filter(key=>!isClearedV771(key)))}
      ${limitsListV771('Checked — nothing to flag',limitsOrderV771.filter(isClearedV771))}
      <p class="muted small" style="margin-top:10px">Peekaa withholds a finding rather than guess. These appear automatically once there is enough evidence.</p>
    </section>`
    :'';

  return `<section class="card ci-owner-brief-v771" aria-labelledby="ciOwnerBriefTitleV771">
    <div class="cui-card-head" style="display:flex;gap:10px;align-items:flex-start">${CUI.icon('customers',{size:24})}<div><h2 id="ciOwnerBriefTitleV771">Owner brief</h2><p>The short version: what happened, who to call, and what is already paid for.</p></div></div>
    ${glanceV771}${bringBackV771}${unusedV771}${topCustomersV771}${servicesV771}${limitsV771}
  </section>`;
}

/* nestly_v650: Service mapping board. Reached from Customer Intelligence's "What they buy"
   withhold state (#/servicemapping) and, when writable, a small link from Services. There is no
   MODULES entry and no route guard for this token — the same shape as #/studio's owner-only
   pattern except the gate here is services-module access, enforced entirely server-side by
   get_service_mapping_board_v1 / set_service_canonical_node_v1 (SECURITY DEFINER, services-gated).
   A denial from the RPC renders the ordinary error card; nothing here re-implements that check. */
async function serviceMappingBoardPage(){
  disposeCurrentRoute();
  const routeMain=M(),isCurrent=()=>routeMain.isConnected&&M()===routeMain;
  routeMain.innerHTML=CUI.loadingState({title:'Map services',iconName:'services',body:'Loading your services…'});
  const canWrite=canWriteModule('services');
  let board=null,loadError='';
  const nodeLabelV650=nodeKey=>{
    if(!nodeKey)return '';
    const node=(board?.nodes||[]).find(n=>n.node_key===nodeKey);
    return node?(node.label||node.node_key):nodeKey;
  };
  const nodeOptionsHtmlV650=selected=>{
    const nodes=Array.isArray(board?.nodes)?board.nodes:[];
    const byPack=new Map();
    nodes.forEach(node=>{
      const pack=node.pack||'Other';
      if(!byPack.has(pack))byPack.set(pack,[]);
      byPack.get(pack).push(node);
    });
    return `<option value="">— Choose —</option>${[...byPack.entries()].map(([pack,packNodes])=>
      `<optgroup label="${esc(pack)}">${packNodes.map(node=>
        `<option value="${esc(node.node_key)}" ${node.node_key===selected?'selected':''}>${'  '.repeat(Math.max(0,Number(node.level||0)))}${esc(node.label||node.node_key)}</option>`
      ).join('')}</optgroup>`
    ).join('')}`;
  };
  function paint(){
    if(!isCurrent())return;
    if(loadError){
      routeMain.innerHTML=CUI.errorState({title:'Map services unavailable',message:ownerErrorText({message:loadError})||loadError});
      const retry=$('routeRetry');
      if(retry)retry.onclick=()=>{
        routeMain.innerHTML=CUI.loadingState({title:'Map services',iconName:'services',body:'Loading your services…'});
        loadBoard();
      };
      return;
    }
    const services=Array.isArray(board?.services)?board.services:[];
    routeMain.innerHTML=`${CUI.pageHeader({title:'Map services',subtitle:'Match each service to a category so What they buy can report on it.',iconName:'services',canWrite,moduleLabel:'Map services'})}
      <div class="card">${services.length?`<div class="cui-table-wrap" role="region" aria-label="Service category map"><table class="cui-table" data-responsive="true"><thead><tr><th>Service</th><th>Old category</th><th>Mapped to</th><th>Suggested</th><th>Choose</th></tr></thead><tbody>${services.map(service=>{
        const current=nodeLabelV650(service.node_key);
        const suggestedLabel=service.suggested_node_key&&!service.node_key?nodeLabelV650(service.suggested_node_key):'';
        return `<tr>
          <td data-label="Service"><b>${esc(service.name||'Service')}</b></td>
          <td data-label="Old category" class="muted small">${esc(service.legacy_category||'—')}</td>
          <td data-label="Mapped to">${current?esc(current):'<span class="muted">—</span>'}</td>
          <td data-label="Suggested">${suggestedLabel?`${esc(suggestedLabel)}${canWrite?` <button class="btn ghost sm" type="button" data-accept-suggestion="${esc(service.service_id)}" data-suggested-node="${esc(service.suggested_node_key)}">Accept</button>`:''}`:'<span class="muted">—</span>'}</td>
          <td data-label="Choose">${canWrite?`<select data-service-select="${esc(service.service_id)}" style="min-height:44px">${nodeOptionsHtmlV650(service.node_key)}</select>`:'<span class="muted small">View only</span>'}</td>
        </tr>`;
      }).join('')}</tbody></table></div>`
        :CUI.emptyState({iconName:'services',title:'No services yet',body:'Add services first, then map them to categories here.'})}
      </div>`;
    CUI.enhance(routeMain);
    if(!canWrite)return;
    routeMain.querySelectorAll('[data-accept-suggestion]').forEach(button=>{
      button.onclick=async()=>{
        const serviceId=button.getAttribute('data-accept-suggestion'),nodeKey=button.getAttribute('data-suggested-node');
        button.disabled=true;
        const {error}=await sb.rpc('set_service_canonical_node_v1',{p_business:S.biz.id,p_service:serviceId,p_node_key:nodeKey});
        if(!isCurrent())return;
        if(error){button.disabled=false;return toast('That mapping could not be saved.')}
        toast('Mapping saved');
        await loadBoard();
      };
    });
    routeMain.querySelectorAll('[data-service-select]').forEach(select=>{
      select.onchange=async()=>{
        const serviceId=select.getAttribute('data-service-select'),nodeKey=select.value;
        if(!nodeKey)return;
        select.disabled=true;
        const {error}=await sb.rpc('set_service_canonical_node_v1',{p_business:S.biz.id,p_service:serviceId,p_node_key:nodeKey});
        if(!isCurrent())return;
        if(error){select.disabled=false;return toast('That mapping could not be saved.')}
        toast('Mapping saved');
        await loadBoard();
      };
    });
  }
  async function loadBoard(){
    const {data,error}=await sb.rpc('get_service_mapping_board_v1',{p_business:S.biz.id});
    if(!isCurrent())return;
    if(error){loadError=error.message||'Map services could not be loaded.';board=null}
    else{loadError='';board=data||{services:[],nodes:[]}}
    paint();
  }
  await loadBoard();
}

/* ---------- reports ---------- */
/* V297 (owner markup on Business Insights, 2026-08-12: "please make business insights more
   interesting & easier to understand" / "i want to know if my business is improving?").
   Every tab opened with a wall of exact figures and no comparison, so nothing on the page
   answered the only question the owner actually asked. The three helpers below are that answer,
   and they are deliberately conservative about it: a verdict is only printed when the previous
   equal-length window is a period this business could really have traded in, and a comparison
   that cannot be made honestly says so rather than inventing a 0% or an infinity. */

/* Is the previous equal-length window a period this business could have records in at all?
   A business whose own record starts inside (or after) that window has no comparable earlier
   period — printing "down 100%" against dates that predate the company would be a fabricated
   verdict, which is exactly what must never appear here. */
/* V300: calendar grains. Month/quarter/year-to-date compare with the SAME ELAPSED span of the
   previous calendar unit; the finished units (last month / last quarter) compare full-vs-full.
   All arithmetic is on date STRINGS via UTC, so no browser timezone can shift a boundary. */
function reportCalendarPresetV300(kind,todayStr){
  const [y,m,d]=String(todayStr).split('-').map(Number);
  const pad=n=>String(n).padStart(2,'0');
  const iso=(yy,mm,dd)=>`${yy}-${pad(mm)}-${pad(dd)}`;
  const lastDay=(yy,mm)=>new Date(Date.UTC(yy,mm,0)).getUTCDate();
  const clampDay=(yy,mm,dd)=>iso(yy,mm,Math.min(dd,lastDay(yy,mm)));
  const addDays=(dateStr,delta)=>{
    const [ay,am,ad]=dateStr.split('-').map(Number);
    const t=new Date(Date.UTC(ay,am-1,ad));t.setUTCDate(t.getUTCDate()+delta);
    return iso(t.getUTCFullYear(),t.getUTCMonth()+1,t.getUTCDate());
  };
  const daysBetween=(a,b)=>Math.round((Date.UTC(...b.split('-').map((v,i)=>i===1?Number(v)-1:Number(v)))
    -Date.UTC(...a.split('-').map((v,i)=>i===1?Number(v)-1:Number(v))))/86400000);
  const prevMonth=(yy,mm)=>mm===1?[yy-1,12]:[yy,mm-1];
  if(kind==='month'){
    const from=iso(y,m,1),[py,pm]=prevMonth(y,m);
    return {from,to:todayStr,cf:iso(py,pm,1),ct:clampDay(py,pm,d)};
  }
  if(kind==='lastmonth'){
    const [py,pm]=prevMonth(y,m),[qy,qm]=prevMonth(py,pm);
    return {from:iso(py,pm,1),to:iso(py,pm,lastDay(py,pm)),cf:iso(qy,qm,1),ct:iso(qy,qm,lastDay(qy,qm))};
  }
  const quarterStartMonth=mm=>mm-((mm-1)%3);
  if(kind==='quarter'){
    const qm=quarterStartMonth(m),from=iso(y,qm,1);
    const [py,pqm]=qm===1?[y-1,10]:[y,qm-3];
    const cf=iso(py,pqm,1);
    return {from,to:todayStr,cf,ct:addDays(cf,daysBetween(from,todayStr))};
  }
  if(kind==='lastquarter'){
    const qm=quarterStartMonth(m);
    const [py,pqm]=qm===1?[y-1,10]:[y,qm-3];
    const [qy,qqm]=pqm===1?[py-1,10]:[py,pqm-3];
    const endMonth=(yy,mm)=>iso(yy,mm+2,lastDay(yy,mm+2));
    return {from:iso(py,pqm,1),to:endMonth(py,pqm),cf:iso(qy,qqm,1),ct:endMonth(qy,qqm)};
  }
  // year to date vs the same dates last year (29 Feb clamps to 28).
  return {from:iso(y,1,1),to:todayStr,cf:iso(y-1,1,1),ct:clampDay(y-1,m,d)};
}
function reportPriorWindowV297(scope){
  const started=String(S.biz?.created_at||'');
  const startedDay=Number.isFinite(Date.parse(started))?sgDateInputValue(new Date(started)):null;
  if(startedDay&&startedDay>scope.priorFrom)
    return {comparable:false,reason:`this business only has records from ${startedDay}`};
  return {comparable:true,reason:''};
}

/* The band that opens every tab: the one number that matters, the change against the previous
   equal-length window, and a plain sentence. `current`/`previous` are the UNDERLYING values
   (cents, hours, counts) so the maths is done on the real figures and only the display is
   rounded; `valueText`/`previousText` are how the calling tab wants them printed.
   Direction is carried three ways on purpose — arrow, colour class and the word itself — because
   an owner reading it at a glance and a screen reader reading it aloud need different cues. */
function reportVerdictBandV297({label,valueText,current,previous,previousText='',days=0,
  available=true,unavailableReason='',zeroBaselineText='nothing was recorded in the previous period',note='',periodLabel=''}={}){
  /* V300: an explicitly chosen baseline (calendar grain or custom compare dates) names itself;
     the derived window keeps the exact V297 phrasing. */
  const periodWords=periodLabel||`the previous ${days} day${days===1?'':'s'}`;
  const currentValue=Number(current),previousValue=Number(previous);
  let tone='none',arrow='',word='',sentence='';
  if(!available||!Number.isFinite(previousValue)||!Number.isFinite(currentValue)){
    /* No fabricated baseline. The figure above still stands on its own. */
    sentence=`No comparable earlier period${unavailableReason?` — ${unavailableReason}`:''}.`;
  }else if(previousValue===0&&currentValue===0){
    tone='flat';arrow='▬';word='unchanged';
    sentence=`Unchanged — nothing recorded in this period or in ${periodWords}.`;
  }else if(previousValue===0){
    /* A percentage from a zero baseline is not a percentage. Say what happened instead. */
    tone='up';arrow='▲';word='up';
    sentence=`Up on ${periodWords} — ${zeroBaselineText}, so there is no percentage to show.`;
  }else{
    const change=(currentValue-previousValue)/Math.abs(previousValue)*100;
    const rounded=Math.abs(change)<0.05?0:change;
    tone=rounded>0?'up':rounded<0?'down':'flat';
    arrow=rounded>0?'▲':rounded<0?'▼':'▬';
    word=rounded>0?'up':rounded<0?'down':'level';
    sentence=rounded===0
      ?`Level with ${periodWords}${previousText?` (${previousText})`:''}.`
      :`${rounded>0?'Up':'Down'} ${Math.abs(rounded).toFixed(1)}% on ${periodWords}${previousText?` (${previousText})`:''}.`;
  }
  return `<section class="report-verdict-v297 report-verdict-${tone}-v297" data-report-verdict-v297="${esc(tone)}" role="status" aria-live="polite">
    <p class="report-verdict-label-v297">${esc(label)}</p>
    <p class="report-verdict-value-v297">${esc(valueText)}</p>
    <p class="report-verdict-change-v297">${arrow?`<span class="report-verdict-arrow-v297" aria-hidden="true">${arrow}</span>`:''}<span data-report-verdict-sentence-v297="${esc(word)}">${esc(sentence)}</span></p>
    ${note?`<p class="muted small report-verdict-note-v297">${esc(note)}</p>`:''}
  </section>`;
}

function growUsageComparisonRangeV392(from,to,basis){
  if(basis==='last_month'||basis==='last_year'){
    const months=basis==='last_year'?12:1;
    return {previousFrom:growUsageShiftMonthsV392(from,months),previousTo:growUsageShiftMonthsV392(to,months),
      days:Math.max(1,daysBetweenSgInputsV153(from,to)),basis};
  }
  return {...previousEquivalentRangeV153(from,to),basis:'previous'};
}
function growUsageQuickRangesV388(today=sgDateInputValue()){
  const monthStart=date=>`${date.slice(0,7)}-01`;
  const [year,month]=today.split('-').map(Number);
  const lastMonthStart=month===1?`${year-1}-12-01`:`${year}-${String(month-1).padStart(2,'0')}-01`;
  /* The day before this month began IS the last day of last month, whatever its length. */
  const lastMonthEnd=shiftSgDateInput(monthStart(today),-1);
  /* getUTCDay on a date-only string is safe: shiftSgDateInput builds it from UTC parts. */
  const weekday=new Date(`${today}T00:00:00Z`).getUTCDay();
  const mondayOffset=weekday===0?-6:1-weekday;
  return [
    {key:'this_week',label:'This week',from:shiftSgDateInput(today,mondayOffset),to:today},
    {key:'last_week',label:'Last week',from:shiftSgDateInput(today,mondayOffset-7),to:shiftSgDateInput(today,mondayOffset-1)},
    {key:'this_month',label:'This month',from:monthStart(today),to:today},
    {key:'last_month',label:'Last month',from:lastMonthStart,to:lastMonthEnd}
  ];
}
function growUsageComparisonChartV386(rows,previousByCategory,previousRange){
  const measured=(rows||[]).filter(row=>row.uses!=null);
  if(measured.length<1)return '';
  const windowed=Boolean(previousByCategory&&previousRange);
  const previousOf=row=>windowed?(previousByCategory.get(row.category)??null):null;
  const peak=Math.max(1,...measured.map(row=>Math.max(Number(row.uses)||0,Number(previousOf(row))||0)));
  if(!measured.some(row=>Number(row.uses)>0||Number(previousOf(row))>0))
    return `<p class="muted small" style="margin-top:12px">Nobody used a programme in this period, so there is nothing to chart yet.</p>`;
  const width=value=>`${Math.max(Number(value)>0?2:0,(Number(value)||0)/peak*100).toFixed(2)}%`;
  const legend=windowed
    ? `<ul class="grow-usage-chart-legend-v386"><li><span class="grow-usage-chart-key-v386 is-now-v386" aria-hidden="true"></span>This period</li><li><span class="grow-usage-chart-key-v386 is-was-v386" aria-hidden="true"></span>${esc(growUsageCompareLabelV392(previousRange))} · ${esc(promotionDateShortV324(previousRange.previousFrom))} – ${esc(promotionDateShortV324(previousRange.previousTo))}</li></ul>`
    : '';
  /* The whole chart is one labelled image to a screen reader: the table above already states
     every figure a row by row reading would repeat. */
  const summary=measured.map(row=>windowed
    ?`${row.category}: ${row.uses} this period, ${previousOf(row)==null?'not tracked':previousOf(row)} previously`
    :`${row.category}: ${row.uses}${row.verbV470?' '+row.verbV470:''}`).join('; ');
  return `<figure class="grow-usage-chart-v386" data-grow-usage-chart-v386>
    <figcaption class="small"><b>${windowed?'This period against the one before it':'Times used, by category'}</b></figcaption>
    ${legend}
    <div class="grow-usage-chart-rows-v386" role="img" data-merchant-content aria-label="${esc(`Times each programme was used. ${summary}`)}">
      ${measured.map(row=>{
        const was=previousOf(row);
        return `<div class="grow-usage-chart-row-v386">
          <span class="grow-usage-chart-label-v386" data-merchant-content>${esc(row.category)}</span>
          <span class="grow-usage-chart-track-v386">
            <span class="grow-usage-chart-bar-v386 is-now-v386" style="width:${width(row.uses)}"></span>
            ${windowed?`<span class="grow-usage-chart-bar-v386 is-was-v386" style="width:${was==null?'0%':width(was)}"></span>`:''}
          </span>
          <span class="grow-usage-chart-value-v386">${esc(String(row.uses))}${row.verbV470?`<small>${esc(row.verbV470)}</small>`:''}${windowed?`<small>${was==null?'not tracked':`was ${esc(String(was))}`}</small>`:''}</span>
        </div>`;
      }).join('')}
    </div>
  </figure>`;
}
const REPORT_SHARE_COLOURS_V297=['var(--chart-1)','var(--chart-2)','var(--chart-3)','var(--chart-4)','var(--chart-5)','var(--chart-6)'];
function reportShareBarV297(entries,{format=value=>String(value)}={}){
  const usable=(entries||[]).filter(([,value])=>Number(value)>0);
  const sum=usable.reduce((total,[,value])=>total+Number(value||0),0);
  if(usable.length<2||sum<=0)return '';
  const share=value=>Number(value)/sum*100;
  const colour=index=>REPORT_SHARE_COLOURS_V297[index%REPORT_SHARE_COLOURS_V297.length];
  return `<div class="report-share-v297">
    ${/* V297: the bar's label and each segment's tooltip are built from the business's own sale
         kinds and its own figures, so they are merchant content — marked the way every other
         data-derived accessibility string in the workspace is, so the locale switcher never
         rewrites a tenant's own words. */''}
    <div class="report-share-bar-v297" data-merchant-content role="img" aria-label="${esc(`Share of the total: ${usable.map(([label,value])=>`${label} ${Math.round(share(value))} percent`).join(', ')}`)}">
      ${usable.map(([label,value],index)=>`<span style="width:${share(value).toFixed(2)}%;background:${colour(index)}" data-merchant-content title="${esc(label)}"></span>`).join('')}
    </div>
    <ul class="report-share-legend-v297">${usable.map(([label,value],index)=>`<li><span class="report-share-dot-v297" aria-hidden="true" style="background:${colour(index)}"></span>${esc(label)} · <b>${esc(format(value))}</b> · ${Math.round(share(value))}%</li>`).join('')}</ul>
  </div>`;
}
/* V551 — the WhatsApp delivery strip on the Bring-back page. The server
   (get_retention_send_stats_v551) owns every count and the template's approval
   status; this only prints. While the Meta template is under review the strip
   says so instead of showing a dead zero — and a suppression total is shown
   with its named reasons, because a refusal the owner cannot see is a support
   ticket, not a safety feature. */
async function loadGrowBbWhatsappStripV551(root){
  const host=(root||document).querySelector('#growBbWhatsappStripV551');
  if(!host)return;
  host.innerHTML='';
  const {data,error}=await sb.rpc('get_retention_send_stats_v551',{p_business:S.biz.id});
  if(error||!data)return;
  if(!host.isConnected)return;
  const n=k=>Number(data[k])||0;
  const reasons=data.suppressed_reasons&&typeof data.suppressed_reasons==='object'?data.suppressed_reasons:{};
  const reasonLabelV551={outbound_off:'messaging is off platform-wide',retention_sends_off:'WhatsApp offers are not switched on yet',capability_disabled:'WhatsApp offers are not enabled for this business',synthetic_client:'demo customers are never messaged',consent_missing:'the customer has not consented to offers',consent_withdrawn:'the customer opted out',whatsapp_consent_absent:'the customer has not opted in to WhatsApp offers yet',whatsapp_consent_withdrawn:'the customer withdrew WhatsApp consent',preference_opt_out:'the customer turned offers off in their app',no_phone:'no valid mobile number on file',customer_opted_out:'the customer replied STOP',stale_unsent:'the offer aged out before sending',cooldown_active:'Peekaa waits 30 days between offers to the same customer',automation_off_for_business:'you switched this message off in WhatsApp automation',platform_hold:'paused by Peekaa for a safety review',business_not_active:'your workspace is not active',demo_business_marketing:'demo businesses are never messaged',platform_channel_off:'WhatsApp is switched off platform-wide',business_not_eligible:'this business is not eligible for WhatsApp offers',synthetic_business:'this is a demo business — never messaged'};
  const reasonBits=Object.entries(reasons).map(([k,v])=>`${Number(v)||0} — ${reasonLabelV551[k]||'not sent — held by a safety check'}`);
  const pending=data.template_status&&data.template_status!=='approved';
  const total=n('queued')+n('sent')+n('delivered')+n('read')+n('failed')+n('suppressed');
  host.innerHTML=`<section class="card" style="margin-top:12px" aria-labelledby="growBbWaTitleV551">
    <b id="growBbWaTitleV551">WhatsApp delivery</b>
    ${pending
      ?`<p class="muted small" style="margin-top:6px">The bring-back message is being reviewed by WhatsApp. Vouchers granted meanwhile queue up and send automatically once it is approved.</p>`
      :`<p class="muted small" style="margin-top:6px">Consenting customers with a phone number get the voucher on WhatsApp automatically.</p>`}
    ${total?`<div class="row" style="gap:14px;flex-wrap:wrap;margin-top:8px">
      ${[['Waiting',n('queued')],['Sent',n('sent')],['Delivered',n('delivered')],['Read',n('read')],['Failed',n('failed')],['Not sent',n('suppressed')]]
        .map(([label,value])=>`<span class="muted small"><b style="font-size:1.15em">${value}</b> ${label}</span>`).join('')}
    </div>`:''}
    ${reasonBits.length?`<p class="muted small" style="margin-top:8px">Not sent because: ${esc(reasonBits.join(' · '))}.</p>`:''}
  </section>`;
}
/* nestly_v583 — the owner's automation control surface.
   Peekaa cannot charge a shop for automation the shopkeeper can neither see nor
   switch off, so every lane that sends on the business's behalf gets a row here
   with plain wording for what the CUSTOMER receives — never how it is delivered.
   Deliberately a PURE top-level function (same posture as recoveryReportHtmlV550)
   so a test can execute it against a fixture and read the real HTML.

   The platform capability is the CEILING and the switch is the floor: a row whose
   capability is not granted renders as unavailable rather than as a toggle that
   would flip a column and still send nothing. A ceiling the owner cannot see is
   indistinguishable, from behind the counter, from a broken product. */
function growWaAutomationCardHtmlV583(state){
  const s=state&&typeof state==='object'?state:{};
  const biz=s.business&&typeof s.business==='object'?s.business:{};
  const caps=s.capabilities&&typeof s.capabilities==='object'?s.capabilities:{};
  const canEdit=s.canEdit===true;
  /* Rows are declared here rather than at module scope so the whole surface is
     one extractable block for the test harness. */
  const rows=[
    {key:'wa_confirmation_enabled',cap:'appointments',title:'Booking confirmation',
     note:'The moment a booking is made, the customer gets a message with the day and time. If the appointment is later moved, they are told the new time the same way.'},
    {key:'wa_reminder_24h_enabled',cap:'appointments',title:'Appointment reminder',
     note:'The day before, the customer gets a short reminder of when to come in.'},
    {key:'wa_reminder_short_enabled',cap:'appointments',title:'Short-notice reminder',
     note:'When a booking is made less than a day ahead, the customer gets one reminder about two hours before.'},
    {key:'wa_bringback_enabled',cap:'bringback',title:'Bring back quiet customers',
     note:'A customer who has not been in for a while gets their bring-back voucher, once per absence.'}
  ];
  const body=rows.map(row=>{
    const granted=caps[row.cap]===true;
    const on=biz[row.key]===true;
    const control=!granted
      ?`<span class="pill off" data-wa-auto-unavailable-v583="${esc(row.key)}">Not included in your plan yet</span>`
      :canEdit
      ?`<button type="button" class="tglsw ${on?'on':''}" data-workspace-i18n data-wa-auto-toggle-v583="${esc(row.key)}" aria-label="${esc(row.title)}" aria-pressed="${on?'true':'false'}"></button>`
      :`<span class="pill ${on?'on':'off'}" data-wa-auto-readonly-v583="${esc(row.key)}">${on?'On':'Off'}</span>`;
    return `<div class="switchrow grow-wa-auto-row-v583" data-wa-auto-row-v583="${esc(row.key)}" style="align-items:flex-start;gap:12px;padding:10px 0;border-top:1px solid var(--hair)">
      <span style="flex:1;min-width:min(100%,200px)"><b>${esc(row.title)}</b>
        <p class="muted small" style="margin:2px 0 0">${esc(row.note)}</p>
        ${!granted?`<p class="muted small" style="margin:4px 0 0">Ask Peekaa to add it and this switch turns on.</p>`:''}</span>
      ${control}</div>`;
  }).join('');
  return `<section class="card" style="margin-top:12px" aria-labelledby="growWaAutoTitleV583">
    <b id="growWaAutoTitleV583">WhatsApp automation</b>
    <p class="muted small" style="margin-top:6px">Messages Peekaa sends to your customers on your behalf. Switch one off and Peekaa stops sending it — nothing else about your shop changes.</p>
    ${canEdit?'':`<p class="muted small" style="margin-top:6px">Only an owner can change these.</p>`}
    <div style="margin-top:8px">${body}</div>
  </section>`;
}
async function loadGrowWaAutomationCardV583(root){
  const host=(root||document).querySelector('#growWaAutomationCardV583');
  if(!host)return;
  host.innerHTML='';
  /* Two reads, one round trip — the appointment lanes and the bring-back lane are
     separate grants, and the owner must see each ceiling for what it is. */
  const [apptCap,bbCap]=await Promise.all([
    sb.rpc('business_get_capability_v518',{p_business:S.biz.id,p_capability:'whatsapp_appointment_notification'}),
    sb.rpc('business_get_capability_v518',{p_business:S.biz.id,p_capability:'whatsapp_retention'})
  ]);
  if(!host.isConnected)return;
  const grantedV583=res=>!res?.error&&res?.data&&res.data.allowed===true;
  const capsV583={appointments:grantedV583(apptCap),bringback:grantedV583(bbCap)};
  const wire=()=>{
    host.querySelectorAll('[data-wa-auto-toggle-v583]').forEach(el=>el.onclick=async()=>{
      const key=el.dataset.waAutoToggleV583,to=!S.biz[key];
      el.disabled=true;
      /* Same write shape as every other business setting (see wireBookingRulesV325):
         a direct owner-scoped update, guarded by salons_update RLS. */
      invalidateBusinessRecordCacheV370();
      const {error}=await sb.from('businesses').update({[key]:to}).eq('id',S.biz.id);
      if(!host.isConnected)return;
      if(error){el.disabled=false;return fail(error)}
      S.biz[key]=to;
      render();
      toast(to?'Switched on — Peekaa will send this.':'Switched off — Peekaa will not send this.');
    });
  };
  const render=()=>{
    host.innerHTML=growWaAutomationCardHtmlV583({business:S.biz,capabilities:capsV583,canEdit:S.myRole==='owner'});
    wire();
  };
  render();
}
/* V550 — the recovered-revenue report renderer, deliberately a PURE top-level function so a
   test can execute it against a fixture payload. Every judgement (lapsed guard, attribution
   window, baseline, net scaling) lives in get_recovery_report_v550; this only prints, and the
   copy states the method rather than hiding it — in a market of inflated claims the audit trail
   IS the feature. The report is business-wide: a bring-back voucher has no branch. */
function recoveryReportHtmlV550(data){
  const d=data&&typeof data==='object'?data:{};
  const iv=d.interventions||{},ret=d.returned||{},rec=d.recovered||{},base=d.baseline||{},net=d.net||{};
  const treated=Number(iv.treated)||0,excluded=Number(iv.excluded_not_lapsed)||0;
  const monthly=Array.isArray(d.monthly)?d.monthly:[];
  if(!treated&&!excluded){
    return `<div class="card">${CUI.emptyState({iconName:'till',title:'No bring-back activity in this period',
      body:'This report measures customers Peekaa helped bring back. It counts two kinds of contact: bring-back vouchers (Grow → Bring-back) and the Message buttons on the Dashboard\u2019s "Customers to bring back" list. Use either, and the recovered revenue appears here.'})}</div>`;
  }
  const pct=v=>v===null||v===undefined?'—':`${Number(v).toFixed(1)}%`;
  const attrDays=Number(d.window?.attribution_days)||30;
  const confidenceNote=d.low_confidence
    ?`<div class="card" style="border-left:3px solid #F0A35B"><b>Small numbers, read with care.</b><p class="muted small" style="margin:6px 0 0">Fewer than 10 contacted customers or fewer than 10 comparison customers in this period — one person changes these percentages a lot.</p></div>`
    :'';
  /* nestly_v653 — the RPC now ships an `evidence` block naming its own comparison group as
     "whoever was not contacted", never a randomised holdout. The headline leads with that
     verdict instead of the dollar figure, so a reader cannot mistake correlation dressed as
     causation for the moat metric it resembles. A response with no `evidence` key (an older
     cached read from before the migration) falls back to the pre-v652 dollar-first card. */
  const headlineHtml=recoveryHeadlineHtmlV652(d.evidence,net,rec,attrDays);
  return `${headlineHtml}
    ${confidenceNote}
    <div class="card"><b>The funnel</b><table style="margin-top:8px">
      <tr><td data-workspace-i18n>Customers contacted while lapsed</td><td class="num"><b>${treated}</b></td></tr>
      <tr><td class="muted small" style="padding-left:14px">by bring-back voucher</td><td class="num">${Number(iv.vouchers)||0}</td></tr>
      <tr><td data-workspace-i18n>Came back within ${attrDays} days</td><td class="num"><b>${Number(ret.count)||0}</b> (${pct(ret.rate_pct)})</td></tr>
      <tr><td data-workspace-i18n>Vouchers actually redeemed</td><td class="num">${Number(rec.redeemed_vouchers)||0} · ${esc(money(rec.redeemed_voucher_cents))}</td></tr></table>
      ${excluded?`<p class="muted small" style="margin-top:8px">${excluded} contact${excluded===1?' was':'s were'} excluded because the customer had visited within the last 14 days — contacting someone who was coming anyway is not a win, and this report refuses to count it.</p>`:''}</div>
    <div class="card"><b>What would have happened anyway</b>
      <p class="muted small" style="margin-top:8px">Of <b>${Number(base.cohort)||0}</b> similar lapsed customers who received no contact, <b>${Number(base.returned)||0}</b> returned on their own (${pct(base.rate_pct)}). The net figure above removes that share.</p></div>
    ${monthly.length?`<div class="card"><b>By month</b><table style="margin-top:8px">
      <tr><th style="text-align:left">Month</th><th class="num">Contacted</th><th class="num">Returned</th><th class="num">Gross</th></tr>
      ${monthly.map(m=>`<tr><td>${esc(m.month||'')}</td><td class="num">${Number(m.interventions)||0}</td><td class="num">${Number(m.returned)||0}</td><td class="num">${esc(money(m.gross_cents))}</td></tr>`).join('')}</table></div>`:''}`;
}
/* V652 helper — pure, same posture as recoveryReportHtmlV550, kept between it and reportsPage
   so the v550 test harness (which slices the file from recoveryReportHtmlV550's declaration to
   reportsPage's) can execute this too without a separate extraction. */
function recoveryPctFmtV652(v){return v===null||v===undefined?'—':`${Number(v).toFixed(1)}%`}
function recoveryHeadlineHtmlV652(evidenceRaw,net,rec,attrDays){
  const evidence=evidenceRaw&&typeof evidenceRaw==='object'?evidenceRaw:null;
  if(!evidence){
    return `<div class="card"><b>Recovered revenue (estimated)</b>
      <div class="metric" style="margin-top:8px">${esc(money(net.cents))}</div>
      <p class="muted small">Net of what would likely have happened anyway. Gross spend by customers who returned within ${attrDays} days of being contacted: <b>${esc(money(rec.gross_cents))}</b>. Whole business, all branches.</p>
      <p class="muted small">Method: ${esc(net.method||'')}</p></div>`;
  }
  /* verdict_ceiling is 'early_signal' — 'strong_pattern' cannot be issued by this RPC. A stray
     value from a future migration is rendered as 'early_signal' defensively rather than trusted
     at face value; anything that isn't literally 'insufficient' takes the early_signal branch. */
  const verdict=evidence.verdict==='insufficient'?'insufficient':'early_signal';
  const sample=evidence.sample&&typeof evidence.sample==='object'?evidence.sample:{};
  const limitations=Array.isArray(evidence.limitations)?evidence.limitations:[];
  const limitationsHtml=limitations.length
    ?`<details class="revenue-truth-limitations"><summary>Limitations</summary><ul>${limitations.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></details>`
    :'';
  if(verdict==='insufficient'){
    return `<section class="revenue-opportunity--withheld" aria-labelledby="recoveryHeadlineHeadingV652">
      <div><span class="revenue-truth-eyebrow">Recovered revenue</span>
      <h2 id="recoveryHeadlineHeadingV652">Not enough signal yet</h2>
      <p>The customers Peekaa contacted cannot yet be told apart from customers who were never contacted — the comparison group here is simply whoever was not reached, not a random holdout. Peekaa is withholding a dollar figure until the two groups can be told apart with confidence.</p>
      <p class="muted small" style="margin-top:8px">Contacted: <b>${Number(sample.treated)||0}</b> (${Number(sample.treated_events)||0} returned) &middot; Comparison: <b>${Number(sample.comparison)||0}</b> (${Number(sample.comparison_events)||0} returned)</p>
      <details style="margin-top:8px"><summary class="muted small" style="cursor:pointer">Estimated figure (not yet reliable)</summary><p class="muted small" style="margin-top:4px">${esc(money(net.cents))} — for reference only; do not quote this while the verdict is "not enough signal".</p></details>
      ${limitationsHtml}
      </div>
    </section>`;
  }
  const rates=evidence.rates&&typeof evidence.rates==='object'?evidence.rates:{};
  const diff=evidence.difference&&typeof evidence.difference==='object'?evidence.difference:null;
  const ppFmt=v=>v===null||v===undefined?'—':`${Number(v)>=0?'+':''}${Number(v).toFixed(1)}pp`;
  const ci=Array.isArray(diff?.confidence_95_pp)?diff.confidence_95_pp:[null,null];
  const diffLine=diff
    ?`Contacted ${recoveryPctFmtV652(rates.treated_pct)} vs ${recoveryPctFmtV652(rates.comparison_pct)} &mdash; difference ${ppFmt(diff.absolute_pp)}, 95% range ${ppFmt(ci[0])} to ${ppFmt(ci[1])}`
    :`Contacted ${recoveryPctFmtV652(rates.treated_pct)} vs ${recoveryPctFmtV652(rates.comparison_pct)}`;
  return `<div class="card"><span class="revenue-truth-eyebrow">Early signal</span>
    <div class="metric" style="margin-top:8px">${esc(money(net.cents))}</div>
    <p class="muted small" style="margin-top:6px">${diffLine}</p>
    <p class="muted small">Net of what would likely have happened anyway. Gross spend by customers who returned within ${attrDays} days of being contacted: <b>${esc(money(rec.gross_cents))}</b>. Whole business, all branches.</p>
    <p class="muted small">Method: ${esc(net.method||'')}</p>
    ${limitationsHtml}
    </div>`;
}
