/* ---------- customer app actions (moved out of Bookings by V223) ---------- */
async function loadCustomerCapabilitiesV223(){
  if(!$('businessCustomerCapabilities'))return;

    const controls=['customerBookingEnabled','customerRedemptionEnabled','customerAppointmentChangesEnabled'];
    const status=$('customerCapabilitiesStatus');
    /* V375: the three switches are split across two tabs now (owner, photo 16), so "save" is
       every Save button on the page — one handler, one RPC, all three values. */
    const saveButtons=[...document.querySelectorAll('.capabilities-save-v375')];
    const save={
      set disabled(value){saveButtons.forEach(button=>{button.disabled=value})},
      set onclick(handler){saveButtons.forEach(button=>{button.onclick=handler})}
    };
    const capabilityResult=await sb.rpc('business_get_customer_capabilities_v89',{p_business:S.biz.id});
    if(!$('businessCustomerCapabilities')?.isConnected)return;
    $('businessCustomerCapabilities').setAttribute('aria-busy','false');
    if(capabilityResult.error){
      status.textContent=capabilityResult.error.code==='PGRST202'||capabilityResult.error.code==='42883'
        ?'These controls need the latest Peekaa service update. All three remain off.'
        :'Customer action settings could not be loaded. Nothing was changed.';
    }else{
      const value=capabilityResult.data||{};
      $('customerBookingEnabled').checked=value.booking_enabled===true;
      $('customerRedemptionEnabled').checked=value.redemption_enabled===true;
      $('customerAppointmentChangesEnabled').checked=value.appointment_changes_enabled===true;
      controls.forEach(id=>$(id).disabled=false);save.disabled=false;
      /* nestly_v633 (owner photo 5: this sentence struck through). It described how the switches
         START, which is only true before anyone has touched them — and by the time it renders,
         the boxes above it are already showing the real state. The line is kept as the STATUS
         line it is (a save writes its result here), so it is blank until it has something true
         to say. */
      status.textContent='';
      /* v294: the booking switch depends on a bookable service existing. Count it once and keep
         the warning in lockstep with the checkbox, so an owner is told at the moment of ticking
         — not weeks later by a customer — why nothing appeared. A failed count stays silent
         rather than crying wolf. */
      const bookableServiceCount=await sb.from('services').select('id',{count:'exact',head:true})
        .eq('business_id',S.biz.id).eq('active',true).eq('show_on_booking_page',true)
        .then(result=>result.error?null:Number(result.count)||0,()=>null);
      if(!$('businessCustomerCapabilities')?.isConnected)return;
      const refreshBookingInertWarningV294=()=>{
        const warning=$('customerBookingInertWarning');if(!warning)return;
        warning.hidden=!($('customerBookingEnabled').checked&&bookableServiceCount===0);
      };
      $('customerBookingEnabled').addEventListener('change',refreshBookingInertWarningV294);
      refreshBookingInertWarningV294();
      /* nestly_v641. v375's arrangement was "a Save button in each card, both running this one
         handler", which is why the two panes could never save contradictory halves. v633 merged
         the appointment switches into the Customer Appointment Request card and deleted the card
         that carried the second button — so the switches ended up in a card whose Save writes
         booking_staff_choice and nothing else, and ticking one there would have been silently
         lost. The handler is published here instead, and that card's Save awaits it: one save,
         one RPC, all three values, exactly as v375 intended. */
      const runCapabilitySaveV634=async()=>{
        save.disabled=true;controls.forEach(id=>$(id).disabled=true);status.textContent='Saving customer actions…';
        const {data,error}=await sb.rpc('business_set_customer_capabilities_v89',{
          p_business:S.biz.id,
          p_booking_enabled:$('customerBookingEnabled').checked,
          p_redemption_enabled:$('customerRedemptionEnabled').checked,
          p_appointment_changes_enabled:$('customerAppointmentChangesEnabled').checked
        });
        if(!$('businessCustomerCapabilities')?.isConnected)return;
        controls.forEach(id=>$(id).disabled=false);save.disabled=false;
        if(error){status.textContent='Customer actions were not changed. Review the settings and try again.';return}
        status.textContent='Customer actions saved. Existing bookings, redemptions, and appointment history remain visible.';
        refreshBookingInertWarningV294();
        toast(data?.replayed===true?'Customer actions were already saved':'Customer actions saved');
      };
      save.onclick=runCapabilitySaveV634;
      customerCapabilitiesSaveV634=runCapabilitySaveV634;
    }
  
}
